$prefix: "ulu";
// Just looping through $config for now (since all are root properties)
// This may need to be adjusted if config is used for something else
@include cssvar.declare-all($config, $prefix);
@include cssvar.declare("scrollbar-width", 0px, $prefix); // Set by JS

@each $name, $props in layout.$widths {
  @include cssvar.declare("width-#{ $name }", $props, $prefix);
}

@each $name, $props in layout.$max-widths {
  @include cssvar.declare("max-width-#{ $name }", $props, $prefix);
}

@include custom-properties();
@include cssvar.declare-breakpoint();
@include cssvar.declare-all($cssvars);

$keys: ();
@each $prop, $theme-map in $tokens {
  @if meta.type-of($theme-map) == 'map' {
    @each $key, $val in $theme-map {
      @if not list.index($keys, $key) {
        $keys: list.append($keys, $key);
      }
    }
  }
}
@return $keys;

@each $name, $definition in $tokens {
  $value: map.get($definition, $key);
  @if ($value != null) {
    @include cssvar.declare($name, $value, $prefix);
  }
}

$schemes: get("color-schemes");
$mapped: map.get($schemes, $theme-name);

@if ($mapped) {
  @return $mapped;
}

@if ($theme-name == "light" or $theme-name == "dark") {
  @return $theme-name;
}

@warn "ULU Themes: No valid color-scheme mapped for theme '#{$theme-name}'. Please add it using `themes.set(( \"color-schemes\" : ( \"#{$theme-name}\": \"light|dark\" ) ))`. The `color-scheme` property will not be output for this theme.";
@return null;

$keys: ();
@each $prop, $theme-map in $tokens {
  @if meta.type-of($theme-map) == 'map' {
    @each $key, $val in $theme-map {
      @if not list.index($keys, $key) {
        $keys: list.append($keys, $key);
      }
    }
  }
}
@return $keys;

@each $name, $definition in $tokens {
  $value: map.get($definition, $key);
  @if ($value != null) {
    @include cssvar.declare($name, $value, $prefix);
  }
}

$prefixMargin: selector.class("adaptive-margin");
$prefixPadding: selector.class("adaptive-padding");
$hasMargin: map.get($config, "outputMargin");
$hasPadding: map.get($config, "outputPadding");

@each $name, $breakpoints in $sizes {
  $sizePrefixMargin: "#{ $prefixMargin }-#{ $name }";
  $sizePrefixPadding: "#{ $prefixPadding }-#{ $name }";
  @each $breakpoint, $props in $breakpoints {
    $direction: map.get($props, "direction");
    $value: map.get($props, "size");
    // If no direction it is the default
    @if $direction == null {
      @if $hasMargin {
        @include -classes-for-type($sizePrefixMargin, "margin", $value);
      }
      @if $hasPadding {
        @include -classes-for-type($sizePrefixPadding, "padding", $value);
      }
    } @else {
      @include breakpoint.from($breakpoint, $direction) {
        @if $hasMargin {
          @include -classes-for-type($sizePrefixMargin, "margin", $value);
        }
        @if $hasPadding {
          @include -classes-for-type($sizePrefixPadding, "padding", $value);
        }
      }
    }
  }
}

