$prefix: selector.class("badge");
// Badge content can be text, image, icon, or background-image
#{ $prefix } {
  display: block;
  width: get("width");
  max-width: 100%;
  flex: 0 0 get("width");
  font-size: get("font-size");
  font-weight: get("font-weight");
  font-family: get("font-family");
}
#{ $prefix }__inner {
  display: block;
  padding-bottom: 100%;
  width: 100%;
  position: relative;
  overflow: hidden;
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center center;
  text-align: center;
  border-radius: get("border-radius");
  transition-property: transform, color, box-shadow, background-color;
  transition-duration: get("transition-duration");
  transition-timing-function: ease-in-out;
  box-shadow: get("box-shadow");
  // In case this is used as a link or router-link
  &,
  &:hover,
  &:focus,
  &:visited {
    background-color: color.get(get("background-color"));
    color: color.get(get("color"));
  }
}
#{ $prefix }--clickable,
button#{ $prefix },
a#{ $prefix } {
  &:hover,
  &:focus {
    #{ $prefix }__inner {
      color: color.get(get("color-hover"));
      background-color: color.get(get("background-color-hover"));
      box-shadow: get("box-shadow-hover");
      transform: scale(get("hover-scale"));
    }
  }
}
#{ $prefix }__inner > * {
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
#{ $prefix }__inner > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  margin: 0 !important;
}

@each $name, $props in get("sizes") {
  #{ $prefix }--#{ $name } {
    width: map.get($props, "width");
    font-size: map.get($props, "font-size");
    flex-basis: map.get($props, "width");
  }
}

