  // Using display flex to allow control for vertical align
  display: flex;
  flex-direction: column;
  justify-content: var(--ulu-basic-hero-main-align, get("main-vertical-align"));

  // Using max/min-width so that we don't need to add selectors to change flex-basis
  // when centered. Using flex-basis: 0 to allow flexbox to decide the items width
  // allows it to expand/shrink within. min(100%... Never larger than parent
  min-width: min(100%, $min-width); 
  max-width: get("main-max-width");
  flex-shrink: 1;
  flex-grow: 1;
  flex-basis: 0;
}
#{ $prefix }__content-media {
  display: flex;
  align-items: center;
  align-self: get("media-vertical-align");
  justify-content: center;
  flex: 0 0 auto; 
  width: min(100%, get("media-max-width"));
}

// Modifiers
#{ $prefix }--center {
  #{ $prefix }__content {
    flex-direction: column;
    flex-wrap: nowrap;
    text-align: center;
    align-items: center;
  }
}

#{ $prefix }--main-start {
  --ulu-basic-hero-main-align: flex-start;
}

#{ $prefix }--main-center {
  --ulu-basic-hero-main-align: center;
}

#{ $prefix }--main-end {
  --ulu-basic-hero-main-align: flex-end;
}

$prefix: selector.class("breadcrumb");

#{ $prefix } {
  color: color.get(get("color"));
  margin: get("margin");
  line-height: get("line-height");
}
#{ $prefix }__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: get("row-gap") 0;
}
#{ $prefix }__item {
  display: flex;
  align-items: center;
}
#{ $prefix }__link,
#{ $prefix }__current {
  white-space: nowrap;
  overflow: hidden;
  max-width: get("item-max-width");
  text-overflow: ellipsis;
}
#{ $prefix }__link {
  color: inherit;
  text-decoration: none;
  &:hover,
  &:focus {
    color: color.get(get("color-hover"));
  }
}
#{ $prefix }__separator {
  margin: get("separator-margin");
  color: color.get(get("separator-color"));
  opacity: get("separator-opacity");
}

