      grid-column: 1 / -1;
      grid-row: 1 / -1;
      border-radius: get("border-radius");
      aspect-ratio: auto;
      img,
      #{ $prefix}__image-media {
        height: 100%;
        object-fit: cover;
        border: 0;
      }
    }
  }

