  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, get("min-width")), 1fr));
  grid-auto-rows: 1fr;
  gap: get("gap");
  margin: get("gap") 0;
  #{ $prefix-card } {
    margin: 0;
    &:not(#{ $prefix-card }--overlay) {
      height: 100%;
    }
  }
}
#{ $prefix }--compact {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, get("compact-min-width")), 1fr));
