  td {
    text-align: get("text-align");
    vertical-align: get("vertical-align");
  }
  th {
    min-width: get("column-min-width");
  }
  td:not(:last-child), 
  th:not(:last-child) {
    border-right: $border;
  }
  // This makes it work for nested headers last child that aren't the last in the table
  th:not(:first-child) {
    border-left: $border;
  }
