$prefix: selector.class("graphic-text-group");

#{ $prefix } {
  display: flex;
  align-items: center;
  text-align: left;
  gap: get("gap");
  margin: get("margin");
}

#{ $prefix }__graphic {
  flex-shrink: 0;
  width: get("graphic-width");
  display: flex;
  align-items: center;
  justify-content: center;
  order: 1;

  img, svg {
    margin: 0;
  }
}

#{ $prefix }__text {
  flex-grow: 1;
  min-width: 0;
  order: 3;
}

// Separator Modifier
#{ $prefix }--separator {
  gap: get("separator-gap");
  &::before {
    content: "";
    display: block;
    order: 2;
    align-self: stretch;
    border-left: get("separator-border");
  }
  &#{ $prefix }--top,
  &#{ $prefix }--bottom {
    &::before {
      border-left: none;
      border-bottom: get("separator-border");
    }
  }
}

// Responsive Modifiers
#{ $prefix }--wrap {
  @include breakpoint.max(get("wrap-breakpoint")) {
    flex-direction: column;
    align-items: flex-start;
    &#{ $prefix }--separator::before {
      border-left: none;
      border-bottom: get("separator-border");
    }
  }
}

// Alignment Modifiers
#{ $prefix }--align-start {
  align-items: flex-start;
}

#{ $prefix }--align-baseline {
  align-items: baseline;
}

#{ $prefix }--align-end {
  align-items: flex-end;
}

// Position Modifiers
#{ $prefix }--right {
  > #{ $prefix }__graphic {
    order: 3;
  }
  > #{ $prefix }__text {
    order: 1;
  }
}

#{ $prefix }--top {
  flex-direction: column;
}

#{ $prefix }--bottom {
  flex-direction: column;
  > #{ $prefix }__graphic {
    order: 3;
  }
  > #{ $prefix }__text {
    order: 1;
  }
}

#{ $prefix }--center {
  align-items: center;
  text-align: center;
}

// Rule Modifiers
#{ $prefix }--rule-top {
  border-top: get("rule-border");
  padding-top: get("rule-padding");
}

#{ $prefix }--rule-bottom {
  border-bottom: get("rule-border");
  padding-bottom: get("rule-padding");
}

// Spacing Modifiers
#{ $prefix }--compact {
  gap: get("gap-compact");
}

// Graphic Modifiers
#{ $prefix }--auto {
  > #{ $prefix }__graphic {
    width: auto;
  }
}

