    opacity: 0; 
    transform: translateX(-15%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translateX(0);
    display: flex;
  }
}
@keyframes uluModalLeftOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translateX(0);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translateX(-15%);
  }
}
@keyframes uluModalRightIn {
  from { 
    opacity: 0; 
    transform: translateX(15%);
