@if (get("arrow-size")) {
  @include -arrow-styles();
}
// Default position is on the right of the container (Popper handles positioning)
#{ $prefix } {
  display: none;
  position: absolute;
  z-index: get("z-index") + 1;
  background-color: color.get(get("background-color"));
  color: color.get(get("color"));
  width: cssvar.use-ulu("popover-width", get("width"));
  max-width: min(cssvar.use-ulu("popover-max-width", 100vw), get("max-width"));
  box-shadow: get("box-shadow");
  border-radius: get("border-radius");
  text-align: left;
  @if (get("type-size")) {
    @include typography.size(get("type-size"));
  }
  &.is-active {
    display: block;
  }
}
#{ $prefix }__inner,
#{ $prefix }__header,
#{ $prefix }__footer {
  display: block;
  border-radius: get("border-radius");
  position: relative;
  z-index: 2; // Above arrow
  flex: 0;
}
#{ $prefix }__inner {
  overflow-y: auto;
  max-height: get("max-height");
  padding: get("padding");
  flex: 1; // When used with footer
}
// Image, video above content
#{ $prefix }__header {
  overflow: hidden;
  padding: get("header-padding-y") get("padding");
  color: color.get(get("header-color"));
  background-color: color.get(get("header-background-color"));
}
#{ $prefix }__header--media {
  padding: 0;
  background-color: color.get(get("header-media-background-color"));
}
#{ $prefix }__footer {
  border-top: get("footer-border-top");
  padding: get("footer-padding-y") get("padding");
  color: color.get(get("footer-color"));
  background-color: color.get(get("footer-background-color"));
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}
#{ $prefix }__header:has(+ #{ $prefix }__inner),
#{ $prefix }__header:has(+ #{ $prefix }__footer),
#{ $prefix }__inner:has(+ #{ $prefix }__footer) {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

// Modifiers
#{ $prefix }--tooltip {
  @include cssvar.declare-ulu("popover-width", get("tooltip-width"));
  @include cssvar.declare-ulu("popover-max-width", get("tooltip-max-width"));
  color: color.get(get("tooltip-color"));
  background-color: color.get(get("tooltip-background-color"));
  pointer-events: none;
  #{ $prefix }__inner {
    padding: get("tooltip-padding");
    min-height: 0;
  }
}
// For fixed strategy
#{ $prefix }--fixed {
  position: fixed;
}
// Allow popover to grow/shrink to content's size
#{ $prefix }--fit {
  @include cssvar.declare-ulu("popover-width", max-content);
}

#{ $prefix }--large {
  @include cssvar.declare-ulu("popover-width", get("width-large"));
}
#{ $prefix }--large-x {
  @include cssvar.declare-ulu("popover-width", get("width-large-x"));
}
#{ $prefix }--large,
#{ $prefix }--large-x {
  #{ $prefix }__inner {
    padding: get("padding-large");
  }
  #{ $prefix }__footer {
    padding: get("footer-padding-y-large") get("padding-large");
  }
}
// If you want to do something custom (and have it touch the edges)
#{ $prefix }--no-padding {
  #{ $prefix }__inner {
    padding: 0;
  }
}
#{ $prefix }--prints {
  @media print {
    display: block;
    position: static;
    width: auto;
    box-shadow: none;
    max-width: none;
    #{ $prefix }__arrow  {
      display: none;
    }
  }
}

