$prefix: selector.class("spoke-spinner");


$size: get("size");
$sizeHalf: math.div($size, 2);

$spoke-width: get("spoke-width");
$spoke-widthHalf: math.div($spoke-width, 2);

#{ $prefix } {
  position: relative;
  vertical-align: middle; // When used as inline-block
}
#{ $prefix }__spinner {
  display: inline-block;
  position: relative;
  width: $size;
  height: $size;
}
