  content: " ";
  display: block;
  position: absolute;
  top: 0;
  left: $sizeHalf - $spoke-widthHalf;
  width: $spoke-width;
  height: get("spoke-height");
  border-radius: get("border-radius");
  background: color.get(get("color"));
}
