    min-width: get("title-min-width");
    padding-top: $mask-offset-top;
    padding-bottom: $mask-offset-bottom;
    text-align: get("title-text-align");
  }
  #{ $prefix }__list,
  #{ $prefix } > ul {
    list-style: none;
    margin: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-self: stretch;
  }
  #{ $prefix }__item,
  #{ $prefix } > ul > li {
