$tabpanel-spacing: utils.get-spacing(get("tabpanel-padding"));

#{ $prefix } {
  margin: get("margin");
}

#{ $prefix }__tablist {
  position: relative;
  z-index: 2;
  display: flex; 
  gap: get("tab-gap");
  overflow-x: auto;
  border-bottom: get("tablist-divider");
  border-bottom-width: get("tablist-divider-width");
  @include layout.remove-scrollbar();
}

#{ $prefix }__tab {
  display: block;
  position: relative; 
  cursor: pointer;
  text-align: center;
  padding: get("tab-padding");
  color: color.get(get("tab-color"));
  font-weight: get("tab-font-weight");
  @if (not get("horizontal-tab-wrap")) {
    white-space: nowrap;
  }
  // Indicator
  &::after {
    content: "";
    position: absolute;
    background-color: color.get(get("indicator-color"));
    opacity: 0;
    bottom: 0;
    left: 0;
    right: 0;
    height: get("indicator-size");
    transition-property: opacity, background-color, transform;
    transition-duration: get("indicator-transition-duration");
    transition-timing-function: get("indicator-transition-timing");
    transform: scaleX(get("indicator-scale-start"));
    transform-origin: center;
  }
  &:hover {
    color: color.get(get("tab-color-hover"));
  }
  // Add focus so as user clicks item it starts the active state styling
  &:focus,
  &[aria-selected="true"] {
    @if get("tab-hide-native-focus") {
      outline: none;
    }
    &::after {
      opacity: 1;
      transform: scaleX(1);
    }
  }
  // Add new focus-specific colors
  // Using :focus-visible so it only applies to keyboard focus
  &:focus-visible,
  &[aria-selected="true"]:focus-visible {
    color: color.get(get("tab-color-focus"));
    background-color: color.get(get("tab-background-color-focus"));
  }
  &[aria-selected="true"] {
    color: color.get(get("tab-color-selected"));
    background-color: color.get(get("tab-background-color-selected"));
  }
}

#{ $prefix }__tabpanel {
  position: relative;
  z-index: 1;
  padding: get("tabpanel-padding");
  overflow: hidden;
  background-color: color.get(get("tabpanel-background-color"));
}

// For images, etc that should fill tabpanel
#{ $prefix }__tabpanel-content-fill {
  margin-left: -(map.get($tabpanel-spacing, "left"));
  margin-right: -(map.get($tabpanel-spacing, "right"));
  width: calc(100% + #{ map.get($tabpanel-spacing, "left") + map.get($tabpanel-spacing, "right") });
  max-width: none;
  &:first-child {
    margin-top: -(map.get($tabpanel-spacing, "top"));
  }
  &:last-child {
    margin-bottom: -(map.get($tabpanel-spacing, "bottom"));
  }
}

#{ $prefix }--sticky {
  > #{ $prefix }__tablist {
    position: sticky;
    top: get("sticky-top");
    z-index: get("sticky-z-index");
    background-color: color.get(get("sticky-background-color"));
  }
}

@include breakpoint.min(get("vertical-breakpoint")) {
  #{ $prefix }--vertical {
    display: grid;
    grid-template-columns: get("vertical-tablist-width") auto; 
    > #{ $prefix }__tablist {
      flex-direction: column;
      gap: get("vertical-tab-gap");
      border-right: get("tablist-divider");
      border-right-width: get("vertical-divider-width");
      border-bottom: none;
      grid-column: 1;
    }
    > #{ $prefix }__tablist > #{ $prefix }__tab {
      padding: get("vertical-tab-padding");
      white-space: normal;
      text-align: left;
      &::after {
        left: utils.when(get("vertical-indicator-left"), 0, auto);
        right: utils.when(not get("vertical-indicator-left"), 0, auto);
        bottom: 0;
        top: 0;
        width: get("indicator-size");
        height: auto;
      }
    }
    > #{ $prefix }__tabpanel {
      grid-column: 2; // needed for equalHeights in vertical
    }
  }
  #{ $prefix }--sticky#{ $prefix }--vertical {
    > #{ $prefix }__tablist {
      top: get("sticky-vertical-top");
      align-self: start;
    }
  }
}

#{ $prefix }--transparent {
  > #{ $prefix }__tablist {
    background-color: transparent;
    padding-left: 0;
    padding-right: 0;
  }
  > #{ $prefix }__tabpanel {
    background-color: transparent;
    padding-left: 0;
    padding-right: 0;
  }
}

#{ $prefix }--full-width {
  > #{ $prefix }__tablist {
    justify-content: safe center;
    background-color: color.get(get("full-width-tablist-background-color"));
  }
  > #{ $prefix }__tabpanel {
    background-color: color.get(get("full-width-tabpanel-background-color"));
    padding: 0;
  }
}

// Display all tabs during print
#{ $prefix }--print {
  @media print {
    #{ $prefix }__tablist {
      display: none;
    }
    #{ $prefix }__tabpanel {
      display: block;
      + #{ $prefix }__tabpanel {
        margin-top: get("print-margin");
      }
    }
  }
}

