$prefix: selector.class("tile-grid");

#{ $prefix } {
  display: grid;
  gap: get("gap");
  grid-template-columns: repeat(auto-fit, minmax(get("width"), 1fr));
  grid-auto-rows: 1fr;
}
#{ $prefix }__item {
  aspect-ratio: get("aspect-ratio");
}
// Use with fill-context, creates the space for images/etc
#{ $prefix }--expanded {
  #{ $prefix }__item {
    width: 100%;
    height: 100%;
    overflow: hidden;
  }
