$prefix: selector.class("button-group");
$prefix-button: selector.class("button");

$button-radius: button.get("border-radius");

#{ $prefix } {
  display: flex;
  flex-wrap: wrap;
  gap: get("gap");
  #{ $prefix-button } {
    margin: 0;
  }
}
#{ $prefix }--joined {
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: get("gap-joined");
  // border-radius: button.get("border-radius");
  #{ $prefix-button } {
    position: relative; // To move to front when hover/active
    border-radius: 0;
    min-width: 0;
    @if (get("gap-joined") == 0) {
      margin-left: -(button.get("border-width"));
    }

    &:first-child {
      border-top-left-radius: $button-radius;
      border-bottom-left-radius: $button-radius;
      margin-left: 0;
    }
    &:last-child {
      border-top-right-radius: $button-radius;
      border-bottom-right-radius: $button-radius;
    }
    #{ button.get("active-selector") } {
      z-index: 2;
    }
    &:hover,
    &:focus {
      z-index: 2;
    }

  }
}

$prefix: selector.class("button-verbose");
$padding-x: get("padding-x");
$padding-y: get("padding-y");
$padding-right: ($padding-x * 2) + 1em;
$cap-side: get("cap-side");
$cap-defaults: (
  "offset" : utils.if-type("number", get("border-width"), 0),
  "border-radius" : utils.when(get("cap-match-radius"), get("border-radius"), 0),
  "padding-adjust" : utils.when(utils.is-side($cap-side), $padding-x, $padding-y)
);

#{ $prefix } {
  position: relative; // For cap and icon
  display: block;
  text-decoration: none;
  border-radius: get("border-radius");
  @if (get("border-width")) {
    border: get("border-width") solid color.get(get("border-color"));
  }
  box-shadow: get("box-shadow");
  line-height: get("line-height");
  margin-bottom: get("margin");
  max-width: 100%;
  width: get("min-width");
  background-color: color.get(get("background-color"));
  padding: $padding-y $padding-right $padding-y $padding-x;
  color: color.get(get("color"));
  text-align: left;

  &:hover,
  &:focus {
    color: color.get(get("color-hover"));
    background-color: color.get(get("background-color-hover"));
    box-shadow: get("box-shadow-hover");
    @if get("title-color-hover") {
      #{ $prefix }__title  {
        color: color.get(get("title-color-hover"));
      }
    }
    @if get("icon-color-hover") {
      #{ $prefix }__icon  {
        color: color.get(get("icon-color-hover"));
      }
    }
  }
  @if get("cap") {
    @include element.cap(
      $side: $cap-side,
      $options: map.merge($cap-defaults, get("cap-options"))
    );
    @if get("cap-options-hover") {
      &:hover,
      &:focus {
        @include element.cap-appearance(
          $side: $cap-side,
          $options: get("cap-options-hover")
        );
      }
    }
  }
}
#{ $prefix }__title,
#{ $prefix }__body {
  display: block;
  &:first-child {
    margin-bottom: get("title-margin");
  }
}
#{ $prefix }__title {
  color: color.get(get("title-color"));
}
#{ $prefix }__icon {
  position: absolute;
  top: 50%;
  right: $padding-x;
  transform: translateY(-50%);
  font-size: get("icon-font-size");
  color: color.get(get("icon-color"));
}
#{ $prefix }--inline {
  display: inline-block;
  margin-right: get("margin-inline");
  &:last-child {
    margin-right: 0;
  }
}
#{ $prefix }--full-width {
  width: 100%;
}

@include utils.file-header('component', 'button');

$prefix: selector.class("button");
// $printContextual: get("contextual-classes");
// $classContextual: "#{ selector.class("button-inside") } ;
$icon-selector: "#{ $prefix }--icon";
$printDescendant: "#{ $prefix }--icon";

#{ $prefix } {
  @include button.default();
}
#{ $prefix }--fit {
  min-width: 0;
}
#{ $prefix }--left {
  justify-content: flex-start;
  text-align: left;
}

@each $size, $values in button.$sizes {
  #{ $prefix }--#{$size} {
    @include button.size($size);
  }
}

@each $style, $values in button.$styles {
  #{ $prefix }--#{$style} {
    @include button.style($style);
  }
}

#{ $icon-selector } {

  min-width: 0;
  max-width: none;
  border-radius: button.get("icon-border-radius");
  font-size: button.get("icon-font-size");
  width: button.get("icon-size");
  height: button.get("icon-size");
  padding: 0 !important;

  #{ $prefix }__icon {
    transform: translateY(get("icon-centered-vertical-offset"));
    margin: 0;
  }
}

@each $size, $values in button.$sizes {
  $icon-size: map.get($values, "icon-size");
  $icon-font-size: map.get($values, "icon-font-size");
  @if ($icon-size or $icon-font-size) {
    #{ $prefix }--#{$size}#{ $icon-selector } {
      width: $icon-size;
      height: $icon-size;
      font-size: $icon-font-size;
    }
  }
}

$prefix: selector.class("panel");

#{ $prefix } {
  display: flex;
  flex-direction: column;
  overflow: get("overflow");
  background-color: get("background-color");
  box-shadow: get("box-shadow");
  border: get("border");
  border-radius: get("border-radius");
}
#{ $prefix }__row {
  &:first-child {
    border-top-left-radius: get("border-radius");
    border-top-right-radius: get("border-radius");
  }
  &:last-child {
    border-bottom-left-radius: get("border-radius");
    border-bottom-right-radius: get("border-radius");
  }
}

@each $modifier, $rows in $styles {
  @if ($modifier == "default") {
    @each $row-name, $props in $rows {
      @if ($row-name == "default") {
        #{ $prefix }__row {
          @include create-row-style($props);
        }
      } @else {
        #{ $prefix }__row--#{ $row-name } {
          @include create-row-style($props);
        }
      }
    }
  } @else {
    #{ $prefix }--#{ $modifier } {
      @each $row-name, $props in $rows {
        @if ($row-name == "default") {
          #{ $prefix }__row {
            @include create-row-style($props);
          }
        } @else {
          #{ $prefix }__row--#{ $row-name } {
            @include create-row-style($props);
          }
        }
      }
    }
  }
}

$prefix: selector.class("progress-bar");

#{ $prefix } {
  line-height: get("line-height");
  margin: get("margin");
}
#{ $prefix }__header {
  display: flex;
  align-items: flex-end;
}
#{ $prefix }__value {
  font-weight: get("value-font-weight");
  color: color.get(get("value-color"));
}
#{ $prefix }__icon {
  color: color.get(get("icon-color"));
}
#{ $prefix }__icon,
#{ $prefix }__header #{ $prefix }__value {
  margin-left: auto;
  padding-left: get("header-gap");
}

#{ $prefix }__track {
  position: relative; // For indeterminate animation
  margin: get("track-margin");
  display: flex;
  width: 100%;
  height: get("bar-height");
  overflow: hidden;
  background-color: color.get(get("track-color"));

  // Remove margins if no children (values/header)
  &:first-child {
    margin-top: 0;
  }
  &:last-child {
    margin-bottom: 0;
  }
}
#{ $prefix }__bar {
  display: flex;
  height: 100%;
  // This is the animation when the component is living in the page
  transition: width get("animation-duration") get("animation-timing"); 
  // This is the initial animation of the bar within itself (ie. filling up)
  &:before {
    content: '';
    display: block;
    width: 100%;
    background-color: color.get(get("bar-color"));
    transform-origin: left center;
    animation: ulu-progress-bar get("animation-initial-duration") forwards get("animation-initial-timing");
  }
}
#{ $prefix }--deficit {
  #{ $prefix }__icon {
    color: color.get(get("icon-color-deficit"));
  }
}
#{ $prefix }__bar--deficit {
  align-items: flex-end;
  margin-left: auto;
  background-color: color.get(get("bar-color-deficit"));
}
#{ $prefix }__values {
  display: flex;
}
#{ $prefix }__values #{ $prefix }__value:not(:last-child) {
  margin-right: get("value-margin");
}
#{ $prefix }__value--deficit {
  margin-left: auto;
  margin-right: get("value-margin-deficit");
  color: color.get(get("value-color-deficit"));
  & + #{ $prefix }__value--total {
    margin-left: 0;
  }
}
#{ $prefix }__value--total {
  margin-left: auto;
  margin-right: 0;
}

@each $name, $props in $styles {
  #{ $prefix }--#{ $name } {
    margin: map.get($props, "margin");
    #{ $prefix }__track {
      height: map.get($props, "bar-height");
      margin: map.get($props, "track-margin");
    }
    #{ $prefix }__bar:before {
      background-color: color.get(map.get($props, "bar-color"));
    }
    #{ $prefix }__track {
      background-color: color.get(map.get($props, "track-color"));
    }
    #{ $prefix }__icon {
      color: color.get(map.get($props, "icon-color"));
    }
  }
}

#{ $prefix }--rounded { 
  #{ $prefix }__track {
    border-radius: get("rounded-border-radius");
  }
}
// For Site Loading (Async Content, not charting/visualization)
#{ $prefix }--indeterminate {
  #{ $prefix }__bar {
    position: absolute;
    top: 0;
    left: 0;
    width: 30%;
    animation: ulu-progress-bar-indeterminate get("animation-indeterminate-duration") linear infinite;
  }
  // &#{ $prefix }--loaded {
  //   #{ $prefix }__bar {
  //     display: none;
  //   }
  // }
}

@keyframes ulu-progress-bar {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes ulu-progress-bar-indeterminate {
  0% {
    left: -100%;
  }
  50% {
    left: 100%;
  }
  100% {
    left: -100%;
  }
}

$prefix: selector.class("spoke-spinner");


$size: get("size");
$sizeHalf: math.div($size, 2);

$spoke-width: get("spoke-width");
$spoke-widthHalf: math.div($spoke-width, 2);

#{ $prefix } {
  position: relative;
  vertical-align: middle; // When used as inline-block
}
#{ $prefix }__spinner {
  display: inline-block;
  position: relative;
  width: $size;
  height: $size;
}
#{ $prefix }__spinner div {
  transform-origin: $sizeHalf $sizeHalf;
  animation: UluFadeOut get("duration") linear infinite;
}
#{ $prefix }__spinner div::after {
  content: " ";
  display: block;
  position: absolute;
  top: 0;
  left: $sizeHalf - $spoke-widthHalf;
  width: $spoke-width;
  height: get("spoke-height");
  border-radius: get("border-radius");
  background: color.get(get("color"));
}
#{ $prefix }__spinner div:nth-child(1) {
  transform: rotate(0deg);
  animation-delay: -1.1s;
}
#{ $prefix }__spinner div:nth-child(2) {
  transform: rotate(30deg);
  animation-delay: -1s;
}
#{ $prefix }__spinner div:nth-child(3) {
  transform: rotate(60deg);
  animation-delay: -0.9s;
}
#{ $prefix }__spinner div:nth-child(4) {
  transform: rotate(90deg);
  animation-delay: -0.8s;
}
#{ $prefix }__spinner div:nth-child(5) {
  transform: rotate(120deg);
  animation-delay: -0.7s;
}
#{ $prefix }__spinner div:nth-child(6) {
  transform: rotate(150deg);
  animation-delay: -0.6s;
}
#{ $prefix }__spinner div:nth-child(7) {
  transform: rotate(180deg);
  animation-delay: -0.5s;
}
#{ $prefix }__spinner div:nth-child(8) {
  transform: rotate(210deg);
  animation-delay: -0.4s;
}
#{ $prefix }__spinner div:nth-child(9) {
  transform: rotate(240deg);
  animation-delay: -0.3s;
}
#{ $prefix }__spinner div:nth-child(10) {
  transform: rotate(270deg);
  animation-delay: -0.2s;
}
#{ $prefix }__spinner div:nth-child(11) {
  transform: rotate(300deg);
  animation-delay: -0.1s;
}
#{ $prefix }__spinner div:nth-child(12) {
  transform: rotate(330deg);
  animation-delay: 0s;
}

// Map of config props needed for a new style, omitting props like color that aren't required
$required: (
  "size" : get("size"),
  "spoke-width" : get("spoke-width"),
  "spoke-height" : get("spoke-height"),
);

@each $name, $style in $styles {
  $merged: map.merge($required, $style);

  $size: map.get($merged, "size");
  $sizeHalf: math.div($size, 2);

  $spoke-width: map.get($merged, "spoke-width");
  $spoke-widthHalf: math.div($spoke-width, 2);

  #{ $prefix }--#{ $name } {
    #{ $prefix }__spinner {
      width: $size;
      height: $size;
    }
    #{ $prefix }__spinner div {
      transform-origin: $sizeHalf $sizeHalf;
      animation-duration: map.get($merged, "duration");
    }
    #{ $prefix }__spinner div::after {
      left: $sizeHalf - $spoke-widthHalf;
      width: $spoke-width;
      height: map.get($merged, "spoke-height");
      border-radius: map.get($merged, "border-radius");
      background: color.get(map.get($merged, "color"));
    }
  }
}

$prefix: selector.class("tag");

#{ $prefix } {
  border-radius: get("border-radius"); 
  display: inline-block;
  padding: get("padding");
  font-weight: get("font-weight");
  vertical-align: get("vertical-align");
  font-style: normal;
  text-overflow: ellipsis;
  text-align: center;
  white-space: nowrap;
  border: get("border-width") solid color.get(get("border-color"));
  background-color: color.get(get("background-color"));
  color: color.get(get("color"));
  font-family: get("font-family");
  line-height: get("line-height");
  @if (typography.has-size(get("type-size"))) {
    @include typography.size(get("type-size"), $only-font-size: true);
  }
  &:not(:last-child) {
    margin-right: get("margin-between");
  }
  &:not(:first-child) {
    margin-left: get("margin-between");
  }
  & + & {
    margin-left: get("margin-between-tags");
  }
}



@each $name, $size in $sizes {
  $type-size: map.get($size, "type-size");

  #{ $prefix }--#{ $name } {
    padding: map.get($size, "padding");  
    line-height: map.get($size, "line-height");
    @if (typography.has-size($type-size)) {
      @include typography.size($type-size, $only-font-size: true);
    }
  }
}

// Order Reason: Needs to inherit from sizes but not styles
#{ $prefix }--counter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: get("counter-size");
  height: get("counter-size");
  border-radius: get("counter-border-radius");
  padding: 0 get("counter-padding-sides");
}

@each $name, $style in $styles {
  #{ $prefix }--#{ $name } {
    background-color: color.get(map.get($style, "background-color")); 
    color: color.get(map.get($style, "color")); 
    border: map.get($style, "border"); 
    border-radius: map.get($style, "border-radius"); 
    border-color: color.get(map.get($style, "border-color")); 
    border-width: map.get($style, "border-width"); 
    box-shadow: map.get($style, "box-shadow"); 
  }
}

$prefix: selector.class("callout");  
$padding: get("padding");
$padding-info: utils.get-spacing($padding);
$cap-options: get("cap-options");
$cap-size: map.get($cap-options, "size");
$cap-side: get("cap-side");

#{ $prefix } {
  position: relative; // For cap
  background-color: color.get(get("background-color"));
  padding: $padding;
  border: get("border-width") solid color.get(get("border-color"));
  margin-bottom: get("margin");
  box-shadow: get("box-shadow");
  border-radius: get("border-radius");
  & >:first-child {
    margin-top: 0;
  }

  // If we have left cap on default we reuse this for all
  // Else we will print it out manually for each unique style
  @if (not get("caps-disabled")) {   
    $cap-defaults: (
      "offset" : get("border-width"),
      "border-radius" : utils.when(get("cap-match-radius"), get("border-radius"), null),
      // "padding-adjust" : map.get($padding-info, $cap-side)
    );
    @include element.cap(
      $side: $cap-side,
      $options: map.merge($cap-defaults, $cap-options)
    );
  }

  // If the left cap is disabled we still include it's CSS but we hide it
  // so that other styles of callouts can use it
  @if (not get("cap")) {
    &::before {
      content: none;
    }
  // Since this is hidden and reused we need to not use padding adjust unless it
  // was visible
  } @else if ($cap-size) {
    padding-#{ $cap-side }: calc(map.get($padding-info, $cap-side) + $cap-size);
  }
}

@include -output-style-modifiers();

$prefix: selector.class("captioned-figure");
$set-aligns: get("text-alignment-matches");
$aligns-center-only: get("text-alignment-matches-center-only");

#{ $prefix } {
  display: block;
  position: relative;
  margin-bottom: get("margin-bottom");
  background-color: color.get(get("background-color"));
  > img {
    width: 100%;
    height: auto;
    margin: 0;
  }
}
a#{ $prefix },
button#{ $prefix } {
  display: block;
  @if (get("box-shadow")) {
    &:hover,
    &:focus {
      box-shadow: get("box-shadow");
    }
  }
}
#{ $prefix }__caption {
  position: absolute;
  color: color.get(get("color"));
  @include typography.size(get("type-size"), $only-font-size: true);
  line-height: get("line-height");
  max-width: get("caption-max-width");
  background-color: color.get(get("caption-background-color"));
  padding: get("caption-padding");
  backdrop-filter: get("caption-backdrop-filter");
}
#{ $prefix }--traditional {
  #{ $prefix }__caption {
    position: static;
    color: color.get(get("traditional-caption-color"));
    max-width: get("traditional-caption-max-width");
    background-color: color.get(get("traditional-caption-background-color"));
    padding: get("traditional-caption-padding");
    text-align: get("traditional-caption-text-align");
    @if (get("traditional-caption-text-align") == right) {
      margin-left: auto;
    }
    @if (get("traditional-caption-text-align") == center) {
      margin-left: auto;
      margin-right: auto;
    }
  }
}
#{ $prefix }--left {
  #{ $prefix }__caption {
    left: 0;
    @if ($set-aligns and not $aligns-center-only) {
      text-align: left;
    }
  }
}
#{ $prefix }--right {
  #{ $prefix }__caption {
    right: 0;
    @if ($set-aligns and not $aligns-center-only) {
      text-align: right;
    }
  }
}
#{ $prefix }--bottom {
  #{ $prefix }__caption {
    bottom: 0;
  }
}
#{ $prefix }--top {
  #{ $prefix }__caption {
    top: 0;
  }
}
#{ $prefix }--bottom#{ $prefix }--center,
#{ $prefix }--top#{ $prefix }--center {
  #{ $prefix }__caption {
    left: 50%;
    transform: translateX(-50%);
    @if ($set-aligns or $aligns-center-only) {
      text-align: center;
    }
  }
}
#{ $prefix }--left#{ $prefix }--center,
#{ $prefix }--right#{ $prefix }--center {
  #{ $prefix }__caption {
    top: 50%;
    transform: translateY(-50%);
  }
}

$prefix: selector.class("card");
$border-width-negative: -(get("border-width"));

#{ $prefix } {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr auto;
  max-width: get("max-width");
  line-height: get("line-height");
  margin-top: get("margin-y");
  margin-bottom: get("margin-y");
  color: color.get(get("color"));
  background-color: color.get(get("background-color"));
  border-radius: get("border-radius");
  border: get("border-width") solid color.get(get("border-color"));
  @if (not get("box-shadow-interactive-only")) {
    box-shadow: get("box-shadow");
  }
  outline: get("border-hover-width") solid transparent;
  outline-offset: $border-width-negative;
}

// Force button element cards to fill available container width (up to max-width)
// instead of shrink-wrapping to intrinsic content width
button#{ $prefix } {
  width: 100%;
}

// Remove extra row when image is not present
// - So footer doesn't fall on the 1fr row
#{ $prefix }:not(:has(> #{ $prefix }__image)),
#{ $prefix }--no-image {
  grid-template-rows: 1fr auto;
}

@if (get("box-shadow-interactive-only") and get("box-shadow")) {
  @include when-clickable() {
    box-shadow: get("box-shadow");
  }
}

@if (get("transition-enabled")) {
  #{ $prefix },
  #{ $prefix }__title {
    transition-duration: get("transition-duration");
    transition-timing-function: get("transition-timing-function");
    transition-property: get("transition-properties");
  }
}

@include when-clickable($hover: true) {
  background-color: color.get(get("background-color-hover"));
  color: color.get(get("color-hover"));
  box-shadow: get("box-shadow-hover");
  outline: get("border-hover-width") solid color.get(get("border-hover-color"));
}

#{ $prefix }__footer,
#{ $prefix }__main,
#{ $prefix }__aside {
  padding: get("padding");
}
#{ $prefix }__body {
  grid-column: 1;
  display: flex;
  flex-direction: column;
  min-height: get("body-min-height");
}
#{ $prefix }__footer {
  grid-column: 1;
  display: flex;
  align-items: center;
  padding-top: get("footer-padding-y");
  padding-bottom: get("footer-padding-y");
  min-height: get("footer-min-height");
  justify-content: get("footer-justify");
  background-color: color.get(get("footer-background-color"));
  border-bottom-left-radius: get("border-radius");
  border-bottom-right-radius: get("border-radius");
}
#{ $prefix }__aside {
  background-color: color.get(get("aside-background-color"));

  @if (get("aside-rule")) {
    // Makes it look like border inside aside padding 
    // without relying on position relative and pseudo technique
    // which affects popovers/etc or other absolute elements inside card
    $aside-rule-color: color.get(get("aside-rule-color"));
    $aside-padding-double: get("padding") * 2;

    background-image: linear-gradient($aside-rule-color, $aside-rule-color);
    background-size: calc(100% - $aside-padding-double) get("aside-rule-width");
    background-position: center top;
    background-repeat: no-repeat;
  }
}

#{ $prefix }__image {
  order: -1;
  grid-column: 1 / -1;
  overflow: hidden; // For image corners with border-radius

  @if (not get("image-within-border")) {
    margin: $border-width-negative $border-width-negative 0 $border-width-negative;
  }

  background-color: color.get(get("image-background-color"));
  border: get("image-border");
  aspect-ratio: get("image-aspect-ratio");
  @if (get("image-margin")) {
    margin: get("image-margin");
  } @else {
    border-top-right-radius: get("border-radius");
    border-top-left-radius: get("border-radius");
  }
}

// Inner Element Styles
#{ $prefix }__title {
  display: block;
  color: color.get(get("title-color"));
  margin-bottom: get("title-margin");
  font-weight: get("title-font-weight");
}
// Only the inner link gets hover state
#{ $prefix }__title-link {
  all: unset;
  cursor: pointer;
  @if get("title-color-hover") {
    &:hover,
    &:focus {
      color: color.get(get("title-color-hover"));
    }
  }
}
// Unless within a clickable card (below)
@if get("title-color-hover") {
  @include when-clickable($hover: true) {
    #{ $prefix }__title {
      color: color.get(get("title-color-hover"));
    }
  }
}
#{ $prefix }__image img,
#{ $prefix}__image-media {
  width: 100%;
  height: 100%;
  object-fit: cover;
  @if (get("image-transition-enabled")) {
    transition-duration: get("image-transition-duration");
    transition-timing-function: get("image-transition-timing-function");
    transition-property: get("image-transition-properties");
  }
}
@if (get("image-transform-hover") or get("image-filter-hover")) {
  @include when-clickable($hover: true) {
    #{ $prefix }__image img,
    #{ $prefix}__image-media {
      transform: get("image-transform-hover");
      filter: get("image-filter-hover");
    }
  }
}

// --- Modifiers ---

// Allows card to fill space (ie. in grid/etc) 
#{ $prefix }--fill {
  max-width: none;
  height: 100%;
  margin: 0;
}

#{ $prefix }--footer-inline {
  #{ $prefix }__footer {
    padding: get("footer-inline-padding");
    flex-direction: column;
    border-bottom-left-radius: 0;
  }
}
// Only add the top-right radius to the footer if there is no image.
// When an image is present, it occupies the top row, meaning the footer 
// sits below it and shouldn't be rounded on the top-right.
#{ $prefix }--footer-inline:not(:has(> #{ $prefix }__image)) {
  #{ $prefix }__footer {
    border-top-right-radius: get("border-radius");
  }
}
#{ $prefix }--footer-inline:not(#{ $prefix }--overlay) {
  // The second column (footer) collapses if unused
  grid-template-columns: 1fr auto;
  #{ $prefix }__footer {
    grid-column: 2;
  }
}
#{ $prefix }--footer-start #{ $prefix }__footer {
  justify-content: start;
}
#{ $prefix }--footer-center #{ $prefix }__footer {
  justify-content: center;
}
#{ $prefix }--footer-end #{ $prefix }__footer {
  justify-content: end;
}


// Makes image centered with max-width for displaying site icon images
#{ $prefix }__image--icon {
  display: flex;
  align-items: center;
  justify-content: center;
  img,
  #{ $prefix}__image-media {
    display: block;
    max-width: get("image-icon-max-width");
    height: auto;
  }
}

// Makes image fit naturally instead of bleed/cover
#{ $prefix }--image-fit {
  #{ $prefix }__image {
    img,
    #{ $prefix}__image-media {
      object-fit: contain;
      object-position: top center;
      padding: get("image-fit-padding");
      filter: get("image-fit-filter");
    }
  }
}

// In case this modifier is being used to hide the image
// not just to tell the component how to layout without image
// - Use case is hiding image when you can't control the output 
//   of the inside of the card (printed no matter what). We had
//   this happen in HHRC, including this extra CSS for that
#{ $prefix }--no-image {
  #{ $prefix }__image {
    display: none;
  }
}

// Horizontal layout
@if (get("horizontal-enabled")) {
  @include breakpoint.min(get("horizontal-breakpoint")) {
    #{ $prefix }--horizontal {
      @include -horizontal-styles();
    }
    #{ $prefix }--horizontal-center {
      @include -horizontal-center-styles();
    }
    #{ $prefix }--horizontal#{ $prefix }--footer-inline {
      @include -horizontal-footer-inline-styles();
    }
  }
}

// Note: Relying on GZIP and identical code for the duplication below
// there's really no way to avoid duplication vs complexity for this
@if (get("horizontal-persist-enabled")) {
  #{ $prefix }--horizontal-persist {
    @include -horizontal-styles();
  }
  #{ $prefix }--horizontal-persist#{ $prefix }--horizontal-center {
    @include -horizontal-center-styles();
  }
  #{ $prefix }--horizontal-persist#{ $prefix }--footer-inline {
    @include -horizontal-footer-inline-styles();
  }
}

// Overlay layout (image under content)
@if (get("overlay-enabled")) {
  #{ $prefix }--overlay {
    // Explanation of aspect-ratio combined with grid-template-rows:
    // - Solves the box growing if needed
    // - First use aspect ration (which grid is based on) but allow the first row 
