          color: color.get(get("overlay-title-color-hover"));
        }
      }
    }
    #{ $prefix }__image {
      grid-column: 1 / -1;
      grid-row: 1 / -1;
      border-radius: get("border-radius");
      aspect-ratio: auto;
      img,
      #{ $prefix}__image-media {
        height: 100%;
        object-fit: cover;
        border: 0;
      }
    }
  }

  @include when-clickable($hover: true) {
    &#{ $prefix }--overlay {
      #{ $prefix }__body,
      #{ $prefix }__footer {
        background-color: color.get(get("overlay-background-color-hover"));
      }
      @if (get("overlay-shading")) {
        #{ $prefix }__body {
          @include -overlay-shading-gradient(
            color.get(get("overlay-background-color-hover"))
          );
        }
      }
    }
  }

  #{ $prefix }--overlay#{ $prefix }--footer-inline {
    grid-template-columns: 1fr auto;
    #{ $prefix }__footer {
      grid-column: 2;
      grid-row: 1 / -1;
      border-radius: 0 get("border-radius") get("border-radius")  0;
    }
  }
}

$prefix: selector.class("card");
$border-width-negative: -(get("border-width"));

#{ $prefix } {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr auto;
  max-width: get("max-width");
  line-height: get("line-height");
  margin-top: get("margin-y");
  margin-bottom: get("margin-y");
  color: color.get(get("color"));
  background-color: color.get(get("background-color"));
  border-radius: get("border-radius");
  border: get("border-width") solid color.get(get("border-color"));
  @if (not get("box-shadow-interactive-only")) {
    box-shadow: get("box-shadow");
  }
  outline: get("border-hover-width") solid transparent;
  outline-offset: $border-width-negative;
}

// Force button element cards to fill available container width (up to max-width)
// instead of shrink-wrapping to intrinsic content width
button#{ $prefix } {
  width: 100%;
}

// Remove extra row when image is not present
// - So footer doesn't fall on the 1fr row
#{ $prefix }:not(:has(> #{ $prefix }__image)),
#{ $prefix }--no-image {
  grid-template-rows: 1fr auto;
}

@if (get("box-shadow-interactive-only") and get("box-shadow")) {
  @include when-clickable() {
    box-shadow: get("box-shadow");
  }
}

@if (get("transition-enabled")) {
  #{ $prefix },
  #{ $prefix }__title {
    transition-duration: get("transition-duration");
    transition-timing-function: get("transition-timing-function");
    transition-property: get("transition-properties");
  }
}

@include when-clickable($hover: true) {
  background-color: color.get(get("background-color-hover"));
  color: color.get(get("color-hover"));
  box-shadow: get("box-shadow-hover");
  outline: get("border-hover-width") solid color.get(get("border-hover-color"));
}

#{ $prefix }__footer,
#{ $prefix }__main,
#{ $prefix }__aside {
  padding: get("padding");
}
#{ $prefix }__body {
  grid-column: 1;
  display: flex;
  flex-direction: column;
  min-height: get("body-min-height");
}
#{ $prefix }__footer {
  grid-column: 1;
  display: flex;
  align-items: center;
  padding-top: get("footer-padding-y");
  padding-bottom: get("footer-padding-y");
  min-height: get("footer-min-height");
  justify-content: get("footer-justify");
  background-color: color.get(get("footer-background-color"));
  border-bottom-left-radius: get("border-radius");
  border-bottom-right-radius: get("border-radius");
}
#{ $prefix }__aside {
  background-color: color.get(get("aside-background-color"));

  @if (get("aside-rule")) {
    // Makes it look like border inside aside padding 
    // without relying on position relative and pseudo technique
    // which affects popovers/etc or other absolute elements inside card
    $aside-rule-color: color.get(get("aside-rule-color"));
    $aside-padding-double: get("padding") * 2;

    background-image: linear-gradient($aside-rule-color, $aside-rule-color);
    background-size: calc(100% - $aside-padding-double) get("aside-rule-width");
    background-position: center top;
    background-repeat: no-repeat;
  }
}

#{ $prefix }__image {
  order: -1;
  grid-column: 1 / -1;
  overflow: hidden; // For image corners with border-radius

  @if (not get("image-within-border")) {
    margin: $border-width-negative $border-width-negative 0 $border-width-negative;
  }

  background-color: color.get(get("image-background-color"));
  border: get("image-border");
  aspect-ratio: get("image-aspect-ratio");
  @if (get("image-margin")) {
    margin: get("image-margin");
  } @else {
    border-top-right-radius: get("border-radius");
    border-top-left-radius: get("border-radius");
  }
}

// Inner Element Styles
#{ $prefix }__title {
  display: block;
  color: color.get(get("title-color"));
  margin-bottom: get("title-margin");
  font-weight: get("title-font-weight");
}
// Only the inner link gets hover state
#{ $prefix }__title-link {
  all: unset;
  cursor: pointer;
  @if get("title-color-hover") {
    &:hover,
    &:focus {
      color: color.get(get("title-color-hover"));
    }
  }
}
// Unless within a clickable card (below)
@if get("title-color-hover") {
  @include when-clickable($hover: true) {
    #{ $prefix }__title {
      color: color.get(get("title-color-hover"));
    }
  }
}
#{ $prefix }__image img,
#{ $prefix}__image-media {
  width: 100%;
  height: 100%;
  object-fit: cover;
  @if (get("image-transition-enabled")) {
    transition-duration: get("image-transition-duration");
    transition-timing-function: get("image-transition-timing-function");
    transition-property: get("image-transition-properties");
  }
}
@if (get("image-transform-hover") or get("image-filter-hover")) {
  @include when-clickable($hover: true) {
    #{ $prefix }__image img,
    #{ $prefix}__image-media {
      transform: get("image-transform-hover");
      filter: get("image-filter-hover");
    }
  }
}

// --- Modifiers ---

// Allows card to fill space (ie. in grid/etc) 
#{ $prefix }--fill {
  max-width: none;
  height: 100%;
  margin: 0;
}

#{ $prefix }--footer-inline {
  #{ $prefix }__footer {
    padding: get("footer-inline-padding");
    flex-direction: column;
    border-bottom-left-radius: 0;
  }
}
// Only add the top-right radius to the footer if there is no image.
// When an image is present, it occupies the top row, meaning the footer 
// sits below it and shouldn't be rounded on the top-right.
#{ $prefix }--footer-inline:not(:has(> #{ $prefix }__image)) {
  #{ $prefix }__footer {
    border-top-right-radius: get("border-radius");
  }
}
#{ $prefix }--footer-inline:not(#{ $prefix }--overlay) {
  // The second column (footer) collapses if unused
  grid-template-columns: 1fr auto;
  #{ $prefix }__footer {
    grid-column: 2;
  }
}
#{ $prefix }--footer-start #{ $prefix }__footer {
  justify-content: start;
}
#{ $prefix }--footer-center #{ $prefix }__footer {
  justify-content: center;
}
#{ $prefix }--footer-end #{ $prefix }__footer {
  justify-content: end;
}


// Makes image centered with max-width for displaying site icon images
#{ $prefix }__image--icon {
  display: flex;
  align-items: center;
  justify-content: center;
  img,
  #{ $prefix}__image-media {
    display: block;
    max-width: get("image-icon-max-width");
    height: auto;
  }
}

// Makes image fit naturally instead of bleed/cover
#{ $prefix }--image-fit {
  #{ $prefix }__image {
    img,
    #{ $prefix}__image-media {
      object-fit: contain;
      object-position: top center;
      padding: get("image-fit-padding");
      filter: get("image-fit-filter");
    }
  }
}

// In case this modifier is being used to hide the image
// not just to tell the component how to layout without image
// - Use case is hiding image when you can't control the output 
//   of the inside of the card (printed no matter what). We had
//   this happen in HHRC, including this extra CSS for that
#{ $prefix }--no-image {
  #{ $prefix }__image {
    display: none;
  }
}

// Horizontal layout
@if (get("horizontal-enabled")) {
  @include breakpoint.min(get("horizontal-breakpoint")) {
    #{ $prefix }--horizontal {
      @include -horizontal-styles();
    }
    #{ $prefix }--horizontal-center {
      @include -horizontal-center-styles();
    }
    #{ $prefix }--horizontal#{ $prefix }--footer-inline {
      @include -horizontal-footer-inline-styles();
    }
  }
}

// Note: Relying on GZIP and identical code for the duplication below
// there's really no way to avoid duplication vs complexity for this
@if (get("horizontal-persist-enabled")) {
  #{ $prefix }--horizontal-persist {
    @include -horizontal-styles();
  }
  #{ $prefix }--horizontal-persist#{ $prefix }--horizontal-center {
    @include -horizontal-center-styles();
  }
  #{ $prefix }--horizontal-persist#{ $prefix }--footer-inline {
    @include -horizontal-footer-inline-styles();
  }
}

// Overlay layout (image under content)
@if (get("overlay-enabled")) {
  #{ $prefix }--overlay {
    // Explanation of aspect-ratio combined with grid-template-rows:
    // - Solves the box growing if needed
    // - First use aspect ration (which grid is based on) but allow the first row 
    // - to grow to min-content if needed (which makes it so the card grows instead 
    // - of overflowing (ie. if you were using "auto auto" or "1fr auto"
    grid-template-rows: minmax(min-content, 1fr) auto;
    aspect-ratio: get("overlay-aspect-ratio");

    #{ $prefix }__body {
      grid-row: 1 / 2;
      align-self: end;
      min-height: 0;
      color: color.get(get("overlay-color"));
      background-color: color.get(get("overlay-background-color"));
      padding-top: get("overlay-body-padding-y");
      padding-bottom: get("overlay-body-padding-y");

      @if (get("overlay-shading")) {
        padding-top: calc(get("overlay-body-padding-y") + get("overlay-shading-height"));
        @include -overlay-shading-gradient(
          color.get(get("overlay-background-color"))
        );
      }
      &:not(:has(~ #{ $prefix }__footer)) {
        border-bottom-left-radius: get("border-radius");
        border-bottom-right-radius: get("border-radius");
      }
    }
    #{ $prefix }__aside { 
      background-color: transparent;
    }
    #{ $prefix }__footer {
      grid-row: 2 / 3;
      background-color: color.get(
        utils.fallback(
          color.get(get("overlay-footer-background-color")), 
          color.get(get("overlay-background-color"))
        )
      );
    }
    #{ $prefix }__body,
    #{ $prefix }__footer {
      color: color.get(get("overlay-color"));
      &:last-child {
        border-bottom-left-radius: get("border-radius");
        border-bottom-right-radius: get("border-radius");
      }
    }
    #{ $prefix }__title {
      color: color.get(
        utils.fallback(color.get(get("overlay-title-color")), color.get(get("overlay-color")))
      );
    }
    @if (get("overlay-title-color-hover")) {
      #{ $prefix }__title-link {
        &:hover,
        &:focus {
          color: color.get(get("overlay-title-color-hover"));
        }
      }
    }
    #{ $prefix }__image {
      grid-column: 1 / -1;
      grid-row: 1 / -1;
      border-radius: get("border-radius");
      aspect-ratio: auto;
      img,
      #{ $prefix}__image-media {
        height: 100%;
        object-fit: cover;
        border: 0;
      }
    }
  }

  @include when-clickable($hover: true) {
    &#{ $prefix }--overlay {
      #{ $prefix }__body,
      #{ $prefix }__footer {
        background-color: color.get(get("overlay-background-color-hover"));
      }
      @if (get("overlay-shading")) {
        #{ $prefix }__body {
          @include -overlay-shading-gradient(
            color.get(get("overlay-background-color-hover"))
          );
        }
      }
    }
  }

  #{ $prefix }--overlay#{ $prefix }--footer-inline {
    grid-template-columns: 1fr auto;
    #{ $prefix }__footer {
      grid-column: 2;
      grid-row: 1 / -1;
      border-radius: 0 get("border-radius") get("border-radius")  0;
    }
  }
}

$prefix: selector.class("card-grid");
$prefix-card: selector.class("card");

#{ $prefix } {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, get("min-width")), 1fr));
  grid-auto-rows: 1fr;
  gap: get("gap");
  margin: get("gap") 0;
  #{ $prefix-card } {
    margin: 0;
    &:not(#{ $prefix-card }--overlay) {
      height: 100%;
    }
  }
}
#{ $prefix }--compact {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, get("compact-min-width")), 1fr));
  gap: get("compact-gap");
}
#{ $prefix }--one-column {
  grid-template-columns: 1fr;
}
#{ $prefix }--rows-fit {
  grid-auto-rows: auto;
}

$prefix: selector.class("counter-list");
$prefix-item: sassSelector.parse("#{ $prefix }__item");
$extra-selector: get("extra-selector");

$selector: $prefix;
$selector-item: sassSelector.parse("#{ $prefix } > li, #{ $prefix-item }");

@if ($extra-selector) {
  $selector: sassSelector.parse("#{ $prefix }, #{ $extra-selector }");
  $selector-item: sassSelector.parse("#{ $selector-item }, #{ $extra-selector } > li");
}

#{ $selector } {
  margin: get("margin");
  counter-reset: ulu-counter-list var(--ulu-counter-list-start, 0);
}

#{ $selector-item } {
  // In case there are lists within (since we're using common var name)
  --ulu-counter-list-start: 0;

  $width: get("counter-width");
  $height: utils.fallback(get("counter-height"), $width);

  display: flex;
  gap: get("counter-gap");
  align-items: get("align-items");
  margin: get("item-margin");
  min-height: $height;
  &::before {
    display: flex;
    align-items: center;
    justify-content: center;
    width: $width;
    height: $height;
    flex: 0 0 $width;
    counter-increment: ulu-counter-list;
    content: counter(ulu-counter-list, get("counter-style"));
    font-size: get("counter-font-size");
    font-family: get("counter-font-family");
    font-weight: get("counter-font-weight");
    color: color.get(get("counter-color"));
    background-color: color.get(get("counter-background-color"));
    border-radius: get("counter-border-radius");
  }

  // Keeping this could be useful
  // but we need to think about how its setup
  // - Probably should be a modifier (choice)
  // - May need either option for how align-items is set (flex-start vs center)
  // - This could be useful when used in grid
  // - May need to be pervasive and not linked to a breakpoint (alternate style)
  // - It's also just useful to know you could override the layout like this 
  //   to get useful variations (maybe we don't need to include it but users 
  //   can do specific)
  // @if ( get("counter-mobile-toggle") ) {
  //   @include breakpoint.max("small") {
  //     padding-left: 0;
  //     padding-top: calc(get("counter-width") + get("counter-gap-mobile"));
  //     flex-direction: column;
  //     align-items: center;
  //   }
  // }
}

// Modifiers
#{ $prefix }--alphabetical {
  & > li::before,
  & > #{ $prefix-item }::before {
    content: counter(ulu-counter-list, upper-alpha);
  }
}
#{ $prefix }--numeric {
  & > li::before,
  & > #{ $prefix-item }::before {
    content: counter(ulu-counter-list, numeric);
  }
}
#{ $prefix }--no-reset {
  counter-reset: none;
}

#{ get("active-selector") } {
  @content;
}

$border: get("stroke-width") solid color.get(get("color"));
$size: get("size");
$stroke-width: get("stroke-width");
$half-height: math.div(get("size"), 2);
$half-stroke-width: math.round(math.div(get("stroke-width"), 2));


.css-icon {
  display: inline-block;
  position: relative;
  width: get("size");
  height: get("size");
  transform-origin: center;
  vertical-align: get("vertical-align");
  font-variant: normal;
  text-rendering: auto;
  line-height: 1;
  margin: get("margin");
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  // Icons that share pseudos for strokes
  &::before,
  &::after {
    // content: "";
    display: block;
    position: absolute;
    width: 100%;
    height: $stroke-width;
    top: 50%;
    left: 50%;
    background-color: color.get(get("color")); 
    transform: translateX(-50%);
    margin-top: -($half-stroke-width);
    border-radius: get("stroke-border-radius");
  }
}
@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  &::before,
  &::after {
    height: $alt-width;
    margin-top: -(math.div($alt-width, 2));
    border-radius: $alt-border-radius;
  }
}
.css-icon--plus,
.css-icon--plus-to-minus,
.css-icon--minus,
.css-icon--close {
  &::before,
  &::after {
    content: "";
  }
}


// Solid icons
[class*="css-icon--circle"],
[class*="css-icon--square"] {
  background-color: color.get(get("color"));
}
[class*="css-icon--circle"] {
  border-radius: 50%;
}

.css-icon--square {
  transform: scale(0.9);
}
.css-icon--square,
.css-icon--circle,
.css-icon--circle-outline,
.css-icon--square-outline {
  &::before,
  &::after {
    content: none;
  }
}
.css-icon--circle-outline,
.css-icon--square-outline {
  background-color: transparent;
  border: $border;
}


.css-icon--circle-info,
.css-icon--circle-question {
  &::before {
    content: "i";
    text-align: center;
    font-size: get("text-size");
    font-family: get("font-family");
    font-weight: bold;
    margin-top: get("text-offset");
    color: color.get(get("color"));
    height: auto;
    left: 0;
    right: 0;
    background-color: transparent;
    filter: invert(1) brightness(1.5);
    transform: translateY(-50%);
  }
  &::after {
    content: none;
  }
}
.css-icon--circle-question { 
  &::before {
    content: "?";
  }
}

[class*="css-icon--arrow"] {
  &::before,
  &::after {
    content: "";
    transform: translateY(-50%);
    margin-top: 0;
  }
}

// Arrow uses same equilateral triangle
[class*="css-icon--triangle"],
[class*="css-icon--arrow"]::after {
  background-color: color.get(get("color"));
  clip-path: polygon(10% 10%, 90% 50%, 10% 90%);
}
[class*="css-icon--arrow"] {
  &::before {
    content: "";
    width: 70%;
    left: 0;
  }
  // Note triangle clip-path is defined above with the solid triangle
  &::after {
    content: "";
    border-radius: 0;
    height: 100%;
    width: 55%;
    right: 0;
    left: auto;
  }
}
[class*="css-icon--angle"] {
  transform: rotate(135deg);
  &::before,
  &::after {
    content: "";
    top: 30%;
    left: 30%;
    width: 70%;    
    transform: none;
    margin-top: 0;
  }
  &::after {
    width: $stroke-width;
    height: 70%;
  }
}
@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  &[class*="css-icon--angle"] {
    &::after {
      width: $alt-width;
    }
  }
}
.css-icon--angle-left,
.css-icon--arrow-left {
  transform: rotate(315deg);
}
.css-icon--angle-up,
.css-icon--angle-up-to-down {
  transform: rotate(45deg);
}
.css-icon--angle-down,
.css-icon--angle-down-to-up {
  transform: rotate(225deg);
}

// Centered pseudos offset by half of stroke before transform
// Icons with centered pseudos

.css-icon--plus,
.css-icon--plus-to-minus {
  &::before {
    transform: translateX(-50%) rotate(90deg);
  }
  &::after {
    transform: translateX(-50%);
  }
}
.css-icon--minus {
  &::before {
    content: none;
  }
  &::after {
    transform: translateX(-50%);
  }
}
.css-icon--close {
  &::before {
    transform: translate(-50%) rotate(45deg);
  }
  &::after {
    transform: translate(-50%) rotate(-45deg);
  }
}
[class*="css-icon--drag"] {
  &::before {
    content: "";
    // Make up for margin-top by default
    margin-top: -(($stroke-width + $stroke-width) * get("drag-gap-multiplier"));
  }
  &::after {
    content: "";
    margin-top: $stroke-width * get("drag-gap-multiplier");
  }
}

@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  // $drag-gap-multiplier: map.get($props, "drag-gap-multiplier");
  // $drag-gap-multiplier: utils.when($drag-gap-multiplier, $drag-gap-multiplier, 0);
  &[class*="css-icon--drag"] {
    &::before {
      margin-top: -(($alt-width + $alt-width) * get("drag-gap-multiplier"));
    }
    &::after {
      margin-top: $alt-width * get("drag-gap-multiplier");
    }
  }
}
// For the menu icon the blocks are stacked with box shadow being the 
// third bar
.css-icon--menu,
.css-icon--menu-to-close {
  display: inline-flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  vertical-align: middle;
  &::before,
  &::after {
    content: "";
    position: static;
    transform: none;
    margin-top: 0;
  }
  &::before {
    box-shadow: 0px ($stroke-width * 2 + 1px) color.get(get("color"));
    margin-bottom: ($stroke-width * 3) + 2px;
  }
}
@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  &.css-icon--menu,
  &.css-icon--menu-to-close {
    &::before {
      box-shadow: 0px ($alt-width * 2 + 1px) color.get(get("color"));
      margin-bottom: ($alt-width * 3) + 2px;
    }
  }
}

// Rotations
.css-icon--triangle-left,
.css-icon--arrow-left {
  transform: rotate(180deg);
}
.css-icon--drag-x,
.css-icon--triangle-up,
.css-icon--arrow-up {
  transform: rotate(270deg);
}
.css-icon--triangle-down,
.css-icon--arrow-down {
  transform: rotate(90deg);
}
.css-icon--drag-both {
  transform: rotate(-45deg);
  &::before {
    transform: translateX(-50%) scale(0.8);
    margin-top: -($stroke-width);
  }
  &::after {
    transform: translateX(-50%) scaleX(0.5) scaleY(0.8);
  }
}

// Active icons
.css-icon--plus-to-minus {
  &,
  &::before,
  &::after {
    transition: get("transition-duration") get("transition-timing-function");
    transition-property: opacity, transform;
  }
  @include when-active() {
    &::before {
      opacity: 0;
      transform: translateX(-50%) rotate(180deg);
    }
  }
}

.css-icon--angle-right-to-down,
.css-icon--angle-up-to-down,
.css-icon--angle-down-to-up {
  @include when-active() {
    transition-duration: get("transition-duration");
