    filter: invert(1) brightness(1.5);
    transform: translateY(-50%);
  }
  &::after {
    content: none;
  }
}
.css-icon--circle-question { 
  &::before {
    content: "?";
  }
}

[class*="css-icon--arrow"] {
  &::before,
  &::after {
    content: "";
    transform: translateY(-50%);
    margin-top: 0;
  }
}

// Arrow uses same equilateral triangle
[class*="css-icon--triangle"],
[class*="css-icon--arrow"]::after {
  background-color: color.get(get("color"));
  clip-path: polygon(10% 10%, 90% 50%, 10% 90%);
}
[class*="css-icon--arrow"] {
  &::before {
    content: "";
    width: 70%;
    left: 0;
  }
  // Note triangle clip-path is defined above with the solid triangle
  &::after {
    content: "";
    border-radius: 0;
    height: 100%;
    width: 55%;
    right: 0;
    left: auto;
  }
}
[class*="css-icon--angle"] {
  transform: rotate(135deg);
  &::before,
  &::after {
    content: "";
    top: 30%;
    left: 30%;
    width: 70%;    
    transform: none;
    margin-top: 0;
  }
  &::after {
    width: $stroke-width;
    height: 70%;
  }
}
@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  &[class*="css-icon--angle"] {
    &::after {
      width: $alt-width;
    }
  }
}
.css-icon--angle-left,
.css-icon--arrow-left {
  transform: rotate(315deg);
}
.css-icon--angle-up,
.css-icon--angle-up-to-down {
  transform: rotate(45deg);
}
.css-icon--angle-down,
.css-icon--angle-down-to-up {
  transform: rotate(225deg);
}

// Centered pseudos offset by half of stroke before transform
// Icons with centered pseudos

.css-icon--plus,
.css-icon--plus-to-minus {
  &::before {
    transform: translateX(-50%) rotate(90deg);
  }
  &::after {
    transform: translateX(-50%);
  }
}
.css-icon--minus {
  &::before {
    content: none;
  }
  &::after {
    transform: translateX(-50%);
  }
}
.css-icon--close {
  &::before {
    transform: translate(-50%) rotate(45deg);
  }
  &::after {
    transform: translate(-50%) rotate(-45deg);
  }
}
[class*="css-icon--drag"] {
  &::before {
    content: "";
    // Make up for margin-top by default
    margin-top: -(($stroke-width + $stroke-width) * get("drag-gap-multiplier"));
  }
  &::after {
    content: "";
    margin-top: $stroke-width * get("drag-gap-multiplier");
  }
}

@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  // $drag-gap-multiplier: map.get($props, "drag-gap-multiplier");
  // $drag-gap-multiplier: utils.when($drag-gap-multiplier, $drag-gap-multiplier, 0);
  &[class*="css-icon--drag"] {
    &::before {
      margin-top: -(($alt-width + $alt-width) * get("drag-gap-multiplier"));
    }
    &::after {
      margin-top: $alt-width * get("drag-gap-multiplier");
    }
  }
}
// For the menu icon the blocks are stacked with box shadow being the 
// third bar
.css-icon--menu,
.css-icon--menu-to-close {
  display: inline-flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  vertical-align: middle;
  &::before,
  &::after {
    content: "";
    position: static;
    transform: none;
    margin-top: 0;
  }
  &::before {
    box-shadow: 0px ($stroke-width * 2 + 1px) color.get(get("color"));
    margin-bottom: ($stroke-width * 3) + 2px;
  }
}
@include for-each-stroke() using ($alt-width, $alt-border-radius) {
  &.css-icon--menu,
  &.css-icon--menu-to-close {
    &::before {
      box-shadow: 0px ($alt-width * 2 + 1px) color.get(get("color"));
      margin-bottom: ($alt-width * 3) + 2px;
    }
  }
}

// Rotations
.css-icon--triangle-left,
.css-icon--arrow-left {
  transform: rotate(180deg);
}
.css-icon--drag-x,
.css-icon--triangle-up,
.css-icon--arrow-up {
  transform: rotate(270deg);
}
.css-icon--triangle-down,
.css-icon--arrow-down {
  transform: rotate(90deg);
}
.css-icon--drag-both {
  transform: rotate(-45deg);
  &::before {
    transform: translateX(-50%) scale(0.8);
    margin-top: -($stroke-width);
  }
  &::after {
    transform: translateX(-50%) scaleX(0.5) scaleY(0.8);
  }
}

// Active icons
.css-icon--plus-to-minus {
  &,
  &::before,
  &::after {
    transition: get("transition-duration") get("transition-timing-function");
    transition-property: opacity, transform;
  }
  @include when-active() {
    &::before {
      opacity: 0;
      transform: translateX(-50%) rotate(180deg);
    }
  }
}

.css-icon--angle-right-to-down,
.css-icon--angle-up-to-down,
.css-icon--angle-down-to-up {
  @include when-active() {
    transition-duration: get("transition-duration");
    transition-property: transform;
  }
}
.css-icon--angle-right-to-down,
.css-icon--angle-up-to-down {
  @include when-active() {
    transform: rotate(225deg);
  }
}
.css-icon--angle-down-to-up {
  @include when-active() {
    transform: rotate(45deg);
  }
}
.css-icon--angle-up-to-down,
.css-icon--angle-down-to-up {
  @include when-active() {
    transition-duration: get("transition-duration") * 2;
  }
}
.css-icon--menu-to-close {
  @include when-active() {
    animation: UluScaleIn get("transition-duration") get("transition-timing-function") forwards;
    &::before,
    &::after {
      position: absolute;
      top: 50%;
      transition: none;
      transform: translate(-50%) rotate(-45deg);
    }
    &::before {
      box-shadow: none;
      transform: translate(-50%) rotate(45deg);
    }
  }
}

@if (not $name) {
  @return get("gutter");
} @else {
  $map: utils.fallback($custom-map, get("extra-breakpoints"));
  $settings: utils.require-map-get($map, $name, "grid [get-gutter]");
  @return map.get($settings, "gutter");
}

$breakpoint: get("breakpoint");
@if ($breakpoint) {
  @return $breakpoint;
} @else {
  @return breakpoint.get("default");
}

$prefix: selector.class("fill-context");

#{ $prefix } {
  position: relative;
}
#{ $prefix }__object,
#{ $prefix }--auto img {
  position: absolute;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

#{ $prefix }--contain {
  &#{ $prefix }--auto img,
  #{ $prefix }__object {
    object-fit: contain;
  }
}

#{ $prefix }--in-grid {
  $breakpoint: data-grid.get-default-breakpoint();
  @include breakpoint.max($breakpoint) {
    #{ $prefix }__object,
    &#{ $prefix }--auto img {
      position: static;
      height: auto;
      object-fit: fill;
    }
  }
}

$attribute-item: "#{ $attribute }-item";
$select-grid: '[#{ $attribute }*="columns: #{ $columns }"]';
$select-grid-not-init: '[#{ $attribute }]:not([#{ $attribute-init }])';
$select-item: '[#{ $attribute-item }]';
$select-rule-col: "::before";
$select-rule-row: "::after";
$select-container: "[#{ $container-attribute }]";
// These through off syntax highlighting when inside interpolation
$position-class-column-first: get("position-class-column-first");
$position-class-column-last: get("position-class-column-last");
$position-class-row-first: get("position-class-row-first");
$position-class-row-last: get("position-class-row-last");

#{ $select-grid } {
  @include layout.clearfix(); // For legacy browsers

  // Ensure empty elements still take up space in layout
  > #{ $select-item } {
    min-height: 1px; 
    width: 100%;
  }
  // This is for value of true and also covers all options below
  &#{'[#{ $attribute }*="gutters-row:"]'} { 
    > #{ $select-item } {
      padding-top:  $gutter;
      padding-bottom: $gutter;
    }
    @if $extra-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        &#{'[#{ $attribute }*="gutter-scale: #{ $scale }"]'} { 
          > #{ $select-item } {
            padding-top:  $gutter * $amount;
            padding-bottom: $gutter * $amount;
          }
        }
      }
    }
  }
  &#{'[#{ $attribute }*="gutters-row: top"]'} { 
    > #{ $select-item } {
      &.#{ $position-class-row-last } {
        padding-bottom: 0;
      }
    }
  }
  &#{'[#{ $attribute }*="gutters-row: bottom"]'} { 
    > #{ $select-item } {
      &.#{ $position-class-row-first } {
        padding-top: 0;
      }
    }
  }
  &#{'[#{ $attribute }*="gutters-row: fit"]'} { 
    margin-top: -$gutter;
    margin-bottom: -$gutter;
    @if $extra-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        &#{'[#{ $attribute }*="gutter-scale: #{ $scale }"]'} { 
          margin-top: -($gutter * $amount);
          margin-bottom: -($gutter * $amount);
        }
      }
    }
  }
  // Rules: Applies to both column and row
  &#{'[#{ $attribute }*="rules"]'} { 
    > #{ $select-item } {
      position: relative;
      @if ($rule-fade-duration) {
        &#{ $select-rule-col },
        &#{ $select-rule-row } {
          // For when grid init fades them in
          opacity: 1;
          transition: opacity $rule-fade-duration ease-in; 
        }
      }
    }
  }
  // Rules: Row
  &#{'[#{ $attribute }*="rules-row:"]'} { 
    > #{ $select-item } {
      &#{ $select-rule-row } {
        position: absolute;
        left: 0;
        right: 0;
        height: $rule-size;
        background: color.get($rule-color);
      }
    }
  }
  // Rules: Column
  &#{'[#{ $attribute }*="rules-column:"]'} { 
    > #{ $select-item } {
      &#{ $select-rule-col } {
        position: absolute;
        top: 0;
        bottom: 0;
        width: $rule-size;
        background: color.get($rule-color);
      }
    }
  }
  // Options for the left or right
  @include -create-rule-col-position(
    $position: "left", 
    $size: $rule-size, 
    $attribute: $attribute, 
    $select-item: $select-item, 
    $select-rule-col: $select-rule-col, 
    $end-class: $position-class-column-first
  );
  @include -create-rule-col-position(
    $position: "right", 
    $size: $rule-size, 
    $attribute: $attribute, 
    $select-item: $select-item, 
    $select-rule-col: $select-rule-col, 
    $end-class: $position-class-column-last
  );
  &#{'[#{ $attribute }*="rules-column-align: gutter"]'} {
    > #{ $select-item } {
      &#{ $select-rule-col } {
        top: $gutter;
        bottom: $gutter;
      }
    }
    @if $extra-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        &#{'[#{ $attribute }*="gutter-scale: #{ $scale }"]'} { 
          > #{ $select-item } {
            &#{ $select-rule-col } {
              top: $gutter * $amount;
              bottom: $gutter * $amount;
            }
          }
        }
      }
    }
  }
  // Options for the left or right
  @include -create-rule-row-position(
    $position: "top", 
    $size: $rule-size, 
    $attribute: $attribute, 
    $select-item: $select-item, 
    $select-rule-row: $select-rule-row, 
    $between: false
  );
  @include -create-rule-row-position(
    $position: "bottom", 
    $size: $rule-size, 
    $attribute: $attribute, 
    $select-item: $select-item, 
    $select-rule-row: $select-rule-row, 
    $between: false
  );

  &#{'[#{ $attribute }*="rules-row: between"]'} {
    > #{ $select-item } {
      &#{ $select-rule-row } {
        bottom: math.floor(math.div($rule-size, 2)) * -1;
      }
      // For removing the rule per row (via equal heights for now)
      &.#{ $position-class-row-last } {
        &#{ $select-rule-row } {
          content: none !important;
        }
      }
    }
  }
  &#{'[#{ $attribute }*="rules-row-align: gutter"]'} {
    > #{ $select-item } {
      &#{ $select-rule-row } {
        @include breakpoint.min($breakpoint) {
          left: $gutter;
          right: $gutter;
        }
      }
    }
    @if $extra-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        &#{'[#{ $attribute }*="gutter-scale: #{ $scale }"]'} { 
          > #{ $select-item } {
            &#{ $select-rule-row } {
              @include breakpoint.min($breakpoint) {
                left: $gutter * $amount;
                right: $gutter * $amount;
              }
            }
          }
        }
      }
    }
  }
  &#{'[#{ $attribute }*="rules-row-persist: true"]'},
  &#{'[#{ $attribute }*="rules-row-stacked-only: true"]'} {
    > #{ $select-item } {
      &#{ $select-rule-row } {
        content: '';
      }
    }
  }
  // IE for mobile/small (non grid / stacked)
  &#{'[#{ $attribute }*="rules-row-stacked-only: true"]'} {
    > #{ $select-item } {
      &#{ $select-rule-row } {
        @include breakpoint.min($breakpoint) {
          content: none !important;
        }
      }
    }
  }
}

@include breakpoint.min($breakpoint) {

  $select-gutter-false: '[#{ $attribute }*="gutters: false"]';
  $select-gutter-false-child: '#{ $select-container }:has(>#{ $select-gutter-false })';

  @if $include-container {
    #{ $select-container } {
      padding-left: $gutter;
      padding-right: $gutter;
    }
    #{ $select-gutter-false-child } {
      padding-left: 0;
      padding-right: 0;
    }
    @if $extra-gutter-scales and $container-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        #{'#{ $select-container }:has(>[#{ $attribute }*="gutter-scale: #{ $scale }"])'} { 
          padding-left: ($gutter * $amount);
          padding-right: ($gutter * $amount);
        }
      }
    }
  }
  // Select the attribute with matching column count
  #{ $select-grid } {
    // Defaults for grid an item
    display: flex;
    flex-flow: row wrap;
    align-items: stretch;
    margin-left: -$gutter;
    margin-right: -$gutter;

    > #{ $select-item } {
      float: left; // Fallback
      padding-left: $gutter;
      padding-right: $gutter;
    }
    > #{'[#{ $attribute-item }*="sticky: top"]'} {
      position: sticky;
      align-self: start;
      top: $sticky-top;
    }
    > #{'[#{ $attribute-item }*="sticky: bottom"]'} {
      position: sticky;
      align-self: end;
      bottom: $sticky-bottom;
    }

    @if $extra-gutter-scales {
      @each $scale, $amount in $extra-gutter-scales {
        &#{'[#{ $attribute }*="gutter-scale: #{ $scale }"]'} { 
          margin-left: -($gutter * $amount);
          margin-right: -($gutter * $amount);

          > #{ $select-item } {
            padding-left: $gutter * $amount;
            padding-right: $gutter * $amount;
          }
        }
      }
    }

    // Alignment options
    &#{'[#{ $attribute }*="justify: center"]'} { 
      justify-content: center;  
    }
    &#{'[#{ $attribute }*="justify: end"]'} { 
      justify-content: flex-end;  
    }
    &#{'[#{ $attribute }*="align: center"]'} { 
      align-items: center;  
    }
    &#{'[#{ $attribute }*="align: end"]'} { 
      align-items: flex-end;
    }
    &#{'[#{ $attribute }*="align: start"]'} { 
      align-items: flex-start; 
    }
    // Alignment of the children when using stretch
    // - There is no stetch-start (that's defualt);
    // - There is no stetch-middle (that's covered by stretch-);
    &#{'[#{ $attribute }*="align: stretch-"]'} { 
      // set the child to display as a single flex item
      > #{ $select-item } {
        display: flex;
        flex-direction: column;
        justify-content: center;
      }
    }
    &#{'[#{ $attribute }*="align: stretch-end"]'} { 
      > #{ $select-item } {
        justify-content: flex-end;
      }
    }
    // Other options
    &#{ $select-gutter-false } { 
      margin-left: 0;
      margin-right: 0;
      > #{ $select-item } {
        padding-left: 0;
        padding-right: 0;
      }
    }
    // Activate Rules
    &#{'[#{ $attribute }*="rules-column:"]'} {
      > #{ $select-item } {
        &#{ $select-rule-col } {
          content: '';
        }
      }
    }
    &#{'[#{ $attribute }*="rules-row:"]'} {
      > #{ $select-item } {
        &#{ $select-rule-row } {
          content: '';
        }
      }
    }
    // Override first or last column removing the rule using matching specificity
    &#{'[#{ $attribute }*="rules-column:"][#{ $attribute }*="rules-column-ends: true"]'} {
      > #{ $select-item } {
        &#{ $select-rule-col } {
          content: '';
        }
      }
    }
    // Generated props for item
    @include -create-column-widths(
      $columns: $columns,
      $attribute-item: $attribute-item,
      $suffix: ''
    );
    @include -create-column-offsets(
      $columns: $columns,
      $attribute-item: $attribute-item,
      $suffix: ''
    );
  }
}
@if $extra-breakpoints {
  @each $name, $options in $extra-breakpoints {
    $g: map.get($options, "gutter");
    @include -create-extra-breakpoint(
      $name: $name, 
      $breakpoint: map.get($options, "breakpoint"),
      $gutter: utils.fallback($g, $gutter),
      $columns: $columns,
      $attribute: $attribute,
      $attribute-item: $attribute-item,
      $select-grid: $select-grid,
      $select-item: $select-item,
      $extra-gutter-scales: $extra-gutter-scales,
      $include-container: $include-container,
      $select-container: $select-container,
      $container-gutter-scales: $container-gutter-scales
    );
  }
}
@if $extra-rule-styles {
  @each $name, $options in $extra-rule-styles {
    $color: utils.require-map-get($options, "color", "grid [extra rule style]");
    $size: utils.require-map-get($options, "size", "grid [extra rule style]");
    #{ $select-grid } {

      &#{'[#{ $attribute }*="rules-column-style: #{ $name }"]'} {
        > #{ $select-item } {
          &#{ $select-rule-col } {
            background-color: color.get($color);
            width: $size;
          }
        }
        @include -create-rule-col-position(
          $position: "left", 
          $size: $size, 
          $attribute: $attribute, 
          $select-item: $select-item, 
          $select-rule-col: $select-rule-col, 
          $end-class: false
        );
        @include -create-rule-col-position(
          $position: "right", 
          $size: $size, 
          $attribute: $attribute, 
          $select-item: $select-item, 
          $select-rule-col: $select-rule-col, 
          $end-class: false
        );
      }
      &#{'[#{ $attribute }*="rules-row-style: #{ $name }"]'} {
        > #{ $select-item } {
          &#{ $select-rule-row } {
            background-color: color.get($color);
            height: $size;
          }
        }
        @include -create-rule-row-position(
          $position: "top", 
          $size: $size, 
          $attribute: $attribute, 
          $select-item: $select-item, 
          $select-rule-row: $select-rule-row, 
          $between: false
        );
        @include -create-rule-row-position(
          $position: "bottom", 
          $size: $size, 
          $attribute: $attribute, 
          $select-item: $select-item, 
          $select-rule-row: $select-rule-row, 
          $between: false
        );
        @include -create-rule-row-position(
          $position: "bottom", 
          $size: $size, 
          $attribute: $attribute, 
          $select-item: $select-item, 
          $select-rule-row: $select-rule-row, 
          $between: true
        );
      }
    }
  }
}

// Disable grid rules until init attribute it present (from positioning script)
// - In order to keep the rules for this compact it will only hide them if the init
//   is not present

@if ($rule-fade-duration) {
  #{ $select-grid-not-init } {
    > #{ $select-item } {
      &#{ $select-rule-col },
      &#{ $select-rule-row } {
        opacity: 0 !important;
      }
    }
  }
}

@include utils.file-header('component', 'data-list');

$prefix: selector.class("data-list");
$stacked-bp: get("stacked-breakpoint");
$overlap: get("overlap-borders");
$border-width: get("border-width");

#{ $prefix } {
  display: grid;

  @if $overlap {
    gap: 0; // Forced to 0 when borders overlap to prevent disjointed negative margins
  } @else {
    gap: var(--ulu-data-list-row-gap, get("row-gap"));
  }

  // Allows inline override via custom property, falls back to config default
  grid-template-columns: var(--ulu-data-list-columns, get("grid-template-columns"));
  list-style: none;
  margin: 0;
  padding: 0;

  @include breakpoint.max($stacked-bp) {
    // Switch to stacked grid template (defaults to 100% stack, but can be overridden for persistent cols)
    grid-template-columns: var(--ulu-data-list-columns-stacked, get("grid-template-columns-stacked"));
  }
}

// Row Item (Passes the grid down)
#{ $prefix }__item {
  display: grid;
  grid-template-columns: subgrid;
  grid-column: 1 / -1;
  gap: var(--ulu-data-list-column-gap, get("column-gap"));
  padding: get("padding");
  background-color: color.get(get("background-color"));
  border: element.optional-border($border-width, get("border-color"));
  border-radius: get("border-radius");
  box-shadow: get("box-shadow");

  @if $overlap {
    margin-top: calc(-1 * #{ $border-width });
    &:first-child {
      margin-top: 0;
    }
  }



  @include breakpoint.max($stacked-bp) {
    // We keep display: grid/subgrid here to respect the stacked parent grid
    gap: var(--ulu-data-list-column-gap-stacked, get("column-gap-stacked")); 
  }

  @if (get("background-color-hover")) {
    &:hover {
      background-color: color.get(get("background-color-hover"));
    }
  }
}

// Interactive z-index management for borders/shadows
#{ $prefix }__item:hover,
#{ $prefix }__item:focus-within,
#{ $prefix }__header #{ $prefix }__item {
  position: relative;
  z-index: 2;
}

// Columns (The cells / wrappers)
#{ $prefix }__column {
  display: flex;
  align-items: center;
  gap: var(--ulu-data-list-column-gap, get("column-gap"));
  // Defensive Layout: Prevents flexbox/grid from refusing to shrink below intrinsic content size.
  // Without this, a long unbroken word or URL could force the column to expand, blowing out the grid.
  // It allows text-overflow: ellipsis to work safely within a column without breaking the layout.
  min-width: 0; 
}

// Automatic Groups (Subgrid on desktop, stack on smaller screens)
#{ $prefix }__column:has(> #{ $prefix }__column) {
  display: grid;
  grid-template-columns: subgrid;
  // Default span is 1, use modifiers below for larger spans

  @include breakpoint.max($stacked-bp) {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: stretch;
    gap: var(--ulu-data-list-group-gap-stacked, get("group-gap-stacked")); // Tighter vertical gap when stacked
  }
}

// Header Row (Optional)
#{ $prefix }__header {
  display: contents; // Removes wrapper so children participate in grid

  // Hide headers when stacked since columns stack
  @include breakpoint.max($stacked-bp) {
    display: none;
  }

  #{ $prefix }__item {
    font-weight: get("header-font-weight");
    background-color: transparent;
    border-bottom: element.optional-border(get("header-border-bottom-width"), get("header-border-bottom-color"));
    border-radius: 0; // Prevent rounding on headers
    &:hover {
      background-color: transparent; // No hover effect on headers
    }
  }
}

// Modifiers

// Structural Edge Modifiers (Decorating the default 1fr track)
#{ $prefix }--prefixed {
  grid-template-columns: var(--ulu-data-list-columns, auto 1fr);
  @include breakpoint.max($stacked-bp) {
    grid-template-columns: var(--ulu-data-list-columns-stacked, auto 1fr);
  }
}
#{ $prefix }--suffixed {
  grid-template-columns: var(--ulu-data-list-columns, 1fr auto);
  @include breakpoint.max($stacked-bp) {
    grid-template-columns: var(--ulu-data-list-columns-stacked, 1fr auto);
  }
}
#{ $prefix }--prefixed#{ $prefix }--suffixed {
  grid-template-columns: var(--ulu-data-list-columns, auto 1fr auto);
  @include breakpoint.max($stacked-bp) {
    grid-template-columns: var(--ulu-data-list-columns-stacked, auto 1fr auto);
  }
}

// Striped Rows
#{ $prefix }--striped {
  @if (get("background-color-even")) {
    #{ $prefix }__item:nth-child(even) {
      background-color: color.get(get("background-color-even"));
    }
  }
}

// Interactive Rows (Proxy Click Support)
// Applied to parent to indicate all rows are interactive
#{ $prefix }--clickable {
  #{ $prefix }__item {
    cursor: pointer;
    &:hover,
    &:focus-within {
      background-color: color.get(get("clickable-background-color-hover"));
      border-color: color.get(get("clickable-border-color-hover"));
    }
  }
}

// Spanning (Required when a subgrid contains multiple child columns)
@for $i from 2 through get("span-count") {
  #{ $prefix }__column--span-#{$i} {
    grid-column: span #{$i};

    // Reset span when stacked so it fits the simplified grid
    @include breakpoint.max($stacked-bp) {
      grid-column: auto;
    }
  }
}

$prefix: selector.class("data-table");
$border: get("border-width") solid color.get(get("border-color"));

$selector-table: sassSelector.parse("#{ $prefix } table, table#{ $prefix }");
$selector-inner: sassSelector.parse($prefix);
$extra-selector: get("extra-selector");

// Allow this to work with wysiwyg class, or as "table" for editor stylesheet
@if ($extra-selector) {
  $selector-table: sassSelector.parse("#{ $selector-table }, #{ $extra-selector }");
  $selector-inner: sassSelector.parse("#{ $selector-inner }, #{ $extra-selector }");
}

// Selector can be on table or wrapping table for convenience
#{ $selector-table } {
  background-color: color.get(get("background-color"));
  border-collapse: collapse;
  border: $border;
  color: color.get(get("color"));
}
#{ $selector-inner } {
  @if (get("type-size") and typography.has-size(get("type-size"))) {
    @include typography.size(get("type-size"), $only-font-size: true);
  }
  line-height: get("line-height");

  caption {
    @if (get("caption-type-size") and typography.has-size(get("caption-type-size"))) {
      @include typography.size(get("caption-type-size"));
    }
    font-weight: get("caption-font-weight");
    text-align: get("caption-text-align");
    margin: get("caption-margin");
    padding: get("caption-padding");
    background-color: get("caption-background-color");
    border-bottom: get("caption-border-bottom");
  }
  th,
  td {
    text-align: get("text-align");
    vertical-align: get("vertical-align");
  }
  th {
    min-width: get("column-min-width");
  }
  td:not(:last-child), 
  th:not(:last-child) {
    border-right: $border;
  }
  // This makes it work for nested headers last child that aren't the last in the table
  th:not(:first-child) {
    border-left: $border;
  }
  tr + tr {
    border-top: $border;
  }
  thead tr {
    background-color: color.get(get("header-background-color"));
  }
  thead th {
    color: color.get(get("header-color"));
  }
  tbody tr {
    background-color: color.get(get("body-background-color"));
  }
  tfoot tr {
    background-color: color.get(get("footer-background-color"));
