$prefix: selector.class("graphic-text-group");

#{ $prefix } {
  display: flex;
  align-items: center;
  text-align: left;
  gap: get("gap");
  margin: get("margin");
}

#{ $prefix }__graphic {
  flex-shrink: 0;
  width: get("graphic-width");
  display: flex;
  align-items: center;
  justify-content: center;
  order: 1;

  img, svg {
    margin: 0;
  }
}

#{ $prefix }__text {
  flex-grow: 1;
  min-width: 0;
  order: 3;
}

// Separator Modifier
#{ $prefix }--separator {
  gap: get("separator-gap");
  &::before {
    content: "";
    display: block;
    order: 2;
    align-self: stretch;
    border-left: get("separator-border");
  }
  &#{ $prefix }--top,
  &#{ $prefix }--bottom {
    &::before {
      border-left: none;
      border-bottom: get("separator-border");
    }
  }
}

// Responsive Modifiers
#{ $prefix }--wrap {
  @include breakpoint.max(get("wrap-breakpoint")) {
    flex-direction: column;
    align-items: flex-start;
    &#{ $prefix }--separator::before {
      border-left: none;
      border-bottom: get("separator-border");
    }
  }
}

// Alignment Modifiers
#{ $prefix }--align-start {
  align-items: flex-start;
}

#{ $prefix }--align-baseline {
  align-items: baseline;
}

#{ $prefix }--align-end {
  align-items: flex-end;
}

// Position Modifiers
#{ $prefix }--right {
  > #{ $prefix }__graphic {
    order: 3;
  }
  > #{ $prefix }__text {
    order: 1;
  }
}

#{ $prefix }--top {
  flex-direction: column;
}

#{ $prefix }--bottom {
  flex-direction: column;
  > #{ $prefix }__graphic {
    order: 3;
  }
  > #{ $prefix }__text {
    order: 1;
  }
}

#{ $prefix }--center {
  align-items: center;
  text-align: center;
}

// Rule Modifiers
#{ $prefix }--rule-top {
  border-top: get("rule-border");
  padding-top: get("rule-padding");
}

#{ $prefix }--rule-bottom {
  border-bottom: get("rule-border");
  padding-bottom: get("rule-padding");
}

// Spacing Modifiers
#{ $prefix }--compact {
  gap: get("gap-compact");
}

// Graphic Modifiers
#{ $prefix }--auto {
  > #{ $prefix }__graphic {
    width: auto;
  }
}

.headline-label {
  display: block;
  margin-bottom: get("margin-bottom");
  font-weight: get("font-weight");
  font-family: get("font-family");
  line-height: get("line-height");
  text-transform: get("text-transform");
  color: color.get(get("color"));
  @if (get("type-size")) {
    @include typography.size(get("type-size"), $only-font-size: true);
  }
}

$prefix: selector.class("hero");
$height: get("height");
$breakpoint: get("breakpoint");

#{ $prefix } {
  display: flex;
  flex-direction: column;
  text-align: get("text-align");
}
#{ $prefix }__content-container {
  padding-top: get("content-padding-top");
  padding-top: get("content-padding-bottom");
}
#{ $prefix }__content-inner {
  max-width: get("content-max-width");
  margin-left: auto;
  margin-right: auto;
}
#{ $prefix }__graphic {
  position: relative;
  flex-grow: 1;
  width: 100%;
}
#{ $prefix }__graphic-media {
  @include layout.absolute-fill(true);
  object-fit: cover;
}



// This doesn't interfere with overlay
#{ $prefix }--top {
  #{ $prefix }__graphic {
    @include breakpoint.min($breakpoint) {
      order: -1;
    }
  }
}
// These are shared between overlay and split style
@include breakpoint.min($breakpoint) {
  #{ $prefix }--right,
  #{ $prefix }--left {
    text-align: right;
    flex-direction: row;
    #{ $prefix }__graphic,
    #{ $prefix }__content {
      flex: 1 0 50%;
    }
    #{ $prefix }__content {
      display: flex;
      flex-direction: column;
      justify-content: center;
    }
  }
  #{ $prefix }--right {
    #{ $prefix }__content-inner {
      margin-right: 0;
    }
  }
  #{ $prefix }--left {
    text-align: left;
    #{ $prefix }__graphic {
      order: -1;
    }
    #{ $prefix }__content-inner {
      margin-left: 0;
    }
  }
}
#{ $prefix }--split {
  @include breakpoint.min($breakpoint) {
    min-height: $height;
  }
  #{ $prefix }__graphic {
    @include breakpoint.max($breakpoint) {
      height: get("graphic-height-stacked");
    }
  }
}

@if get("extra-split-ratios") {
  @include breakpoint.min($breakpoint) {
    @each $name, $ratio in get("extra-split-ratios") {
      #{ $prefix }--split-graphic-#{ $name } #{ $prefix }__graphic,
      #{ $prefix }--split-content-#{ $name } #{ $prefix }__content {
        flex-basis: list.nth($ratio, 1);
      }
      #{ $prefix }--split-graphic-#{ $name } #{ $prefix }__content,
      #{ $prefix }--split-content-#{ $name } #{ $prefix }__graphic {
        flex-basis: list.nth($ratio, 2);
      }
    }
  }
}


#{ $prefix }--overlay {
  position: relative;
  justify-content: center;
  min-height: $height;
  #{ $prefix }__content { 
    position: relative;
    z-index: 2;
  }
  #{ $prefix }__graphic {
    @include layout.absolute-fill();
  }
  &#{ $prefix }--bottom,
  &#{ $prefix }--bottom #{ $prefix }__content {
    justify-content: flex-end;
  }
  &#{ $prefix }--top,
  &#{ $prefix }--top #{ $prefix }__content {
    justify-content: flex-start;
  }
}
#{ $prefix }--compact {
  min-height: get("height-compact");
}

$prefix: selector.class("image-grid");
$gap: get("gap");

#{ $prefix } {
  display: flex;
  flex-wrap: wrap;
  margin: -($gap);
  overflow: hidden;
}
#{ $prefix }__item {
  // Have to use borders vs flexbox gap (adds to percentages) @important
  border-bottom: $gap solid transparent;
  border-top: $gap solid transparent;
  @include breakpoint.min(get("breakpoint")) {
    border: $gap solid transparent;
    flex: 1 1;
    min-width: get("min-width");
  }
  > img {
    width: 100%;
  }
}

$prefix: selector.class("input-group");

$radius: get("border-radius") or form-theme.get("input-border-radius");
$border-info: utils.border-info(form-theme.get("input-border"));
$overlap: get("overlap-margin") or map.get($border-info, "width");

$padding-y: get("item-padding-y") or utils.get-spacing-top(button.get("padding"));
$padding-x: get("item-padding-x");

#{ $prefix } {
  display: flex;
  align-items: stretch;
  max-width: 100%;
  gap: get("gap");
}

#{ $prefix }__item {
  position: relative; // For z-index management
  display: flex;
  align-items: stretch;
  flex: 0 1 auto; 
  min-width: cssvar.use-ulu("input-group-item-min-width", get("item-min-width"));
}

#{ $prefix }__item--field {
  flex: 1 1 auto; 
  min-width: cssvar.use-ulu("input-group-field-min-width", get("field-min-width"));
}

#{ $prefix }__item--cue {
  padding: $padding-y $padding-x;
  align-items: center;
  background-color: cssvar.use-ulu("input-group-cue-background", get("cue-background-color"));
  border: form-theme.get("input-border");
  border-radius: $radius;
  color: form-theme.get("color");
  line-height: typography.get("line-height-dense");
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

// Specificity overrides for internal elements
#{ $prefix } {
  #{ $prefix }__input,
  #{ $prefix }__button {
    height: 100%;
    margin: 0;
    min-width: 0; 
    max-width: none;
  }

  #{ $prefix }__input {
    width: 100%;
  }
}

// Removes internal border-radius and overlaps borders
#{ $prefix }--joined {
  gap: 0;

  // Remove default button padding when joined only
  #{ $prefix }__button { 
    padding-left: $padding-x;
    padding-right: $padding-x;
    @if (get("joined-button-radius-match")) {
      border-radius: $radius;
    }
  }

  // Interactive items pop to front (cues do not have focus/hover states)
  #{ $prefix }__item:not(#{ $prefix }__item--cue) {
    &:hover,
    &:focus-within {
      z-index: 2;
    }
  }

  // Strip left radius for items after the first
  #{ $prefix }__item:not(:first-child) {
    margin-left: -#{ $overlap }; // Use resolved overlap width

    &#{ $prefix }__item--cue,
    #{ $prefix }__input, 
    #{ $prefix }__button {
      border-top-left-radius: 0;
      border-bottom-left-radius: 0;
    }
  }

  // Strip right radius for items before the last
  #{ $prefix }__item:not(:last-child) {
    &#{ $prefix }__item--cue,
    #{ $prefix }__input, 
    #{ $prefix }__button {
      border-top-right-radius: 0;
      border-bottom-right-radius: 0;
    }
  }
}

$selector: selector.class("links");
$selectorSingle: selector.class("link");
$selectorNot: "#{ $selector }--no-visited";
$selectorSingleNot: "#{ $selectorSingle }--no-visited";
// Using not to avoid duplicating css
// There shouldn't be to many reasons to need to override these styles
#{ $selector }:not(#{ $selectorNot }) a,
#{ $selectorSingle }:not(#{ $selectorSingleNot }) {
    @include element.link(true, true);
  }
#{ $selector }--no-visited a,
#{ $selectorSingle }--no-visited {
    @include element.link();
  }
// Chained to match not() specifity
#{ $selector }#{ $selector }--no-underline a,
#{ $selectorSingle }#{ $selectorSingle }--no-underline {
  text-decoration: none;
}

$prefix: selector.class("list-inline");
$border: element.get-rule-style(get("rule-style"));

ul#{ $prefix },
#{ $prefix } ul {
  list-style: none;
  display: inline-flex;
  flex-wrap: wrap;
  margin: get("margin-top") 0 get("margin-bottom") 0;
}
#{ $prefix } {
  li {
    // Not using flex gap because we would need to position
    // pseudo for divider, so we would still need to use math
    // So custom properties couldn't be used (no benefit)
    padding-right: get("space-between");
    margin-right: get("space-between");
    border-right: $border;
    &:last-child {
      border-right: none;
      padding-right: 0;
      margin-right: 0;
    }
  }
}
#{ $prefix }--large-gap {
  li {
    padding-right: get("space-between-large");
    margin-right: get("space-between-large");
  }
}

$prefix: selector.class("list-lines");
$border: element.get-rule-style(get("rule-style"));

#{ $prefix } {
  list-style: none;
  margin: get("margin-top") 0 get("margin-bottom") 0;
  padding: 0;
  @if (get("border-first")) {
    border-top: $border;
  }
  >li {
    border-bottom: $border;
    padding: get("padding-between") 0;
    >*:last-child {
      margin-bottom: 0;
    }
    @if (not get("border-last")) {
      &:last-child {
        border-bottom-width: 0;
      }
    }
  }
}
#{ $prefix }--dense {
  >li {
    padding: get("dense-padding-between") 0;
    line-height: get("dense-line-height");
  }
}

$prefix: selector.class("list-ordered");
#{ $prefix } {
  @include element.styles-ordered-list();
}

$prefix: selector.class("list-unordered");
#{ $prefix } {
  @include element.styles-unordered-list();
  li {
    &::marker {
      color: color.get("bullet");
    }
  }
}

$prefix: selector.class("menu-stack");
$prefix-name-only: selector.class("menu-stack", $name-only: true);
$prefix-popover: selector.class("popover");
$selectable-y: (get("link-padding-y") + get("link-margin"));

#{ $prefix } {
  @include cssvar.declare-ulu("menu-stack-link-padding-x", get("link-padding-x"));
}

#{ $prefix }--separated {
  border-top: element.get-rule-style(get("rule-style"));
  padding-top: get("rule-margin");
  margin-top: get("rule-margin");
}
#{ $prefix }__label {
  text-transform: get("label-text-transform");
  padding-bottom: get("label-margin");
  color: color.get(get("label-color"));
  font-weight: get("label-font-weight");
  line-height: get("label-line-height");
  @if (get("label-type-size")) {
    @include typography.size(get("label-type-size"), $only-font-size: true);
  }
}
#{ $prefix }__item--separator-before {
  border-top: element.get-rule-style(-fallback("link-separated-rule-style", "rule-style"));
  margin-top: -fallback("link-separated-margin", "link-padding-y");
  padding-top: -fallback("link-separated-margin", "link-padding-y");
}
#{ $prefix }__item--separator-after {
  border-bottom: element.get-rule-style(-fallback("link-separated-rule-style", "rule-style"));
  margin-bottom: -fallback("link-separated-margin", "link-padding-y");
  padding-bottom: -fallback("link-separated-margin", "link-padding-y");
}
#{ $prefix }__list {
  & & {
    padding-left: get("nested-indent");
  }
}

// Special modifier for item to style as a title
// - Used in columns menus where first level isn't in a <ul> but is just above 
//   the <ul> and being styled as though it was to match the styling of the menu 
//   of children
// - Note: This is output above the link styling for specificity, so it will 
//   fallback to link colors for hover/active
#{ $prefix }__item--title {
  @if get("title-separator-enabled") {
    border-bottom: element.get-rule-style(-fallback("title-rule-style", "rule-style"));
    margin-bottom: -fallback("title-separated-margin", "link-padding-y");
    padding-bottom: -fallback("title-separated-margin", "link-padding-y");
  }
  &,
  > #{ $prefix }__link {
    color: color.get(get("title-color"));
    font-weight: get("title-font-weight");
  }
}


// By default the link hangs outside the container so that 
// the icons/text align to the text (above/below)
// - Use the modifier "site-menu--contained" to keep the links within 
//   the parent container (no optical alignment), should be within something that contains it

#{ $prefix }__link,
#{ $prefix }__selectable,
#{ $prefix }__toggle {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  width: 100%;
  padding: get("link-padding-y") cssvar.use-ulu("menu-stack-link-padding-x");
  margin: get("link-margin") 0;
  border-radius: get("link-border-radius");
  font-weight: get("link-font-weight");
  line-height: get("link-line-height");
  color: color.get(get("link-color"));
  background-color: color.get(get("link-background-color"));
  transition-duration: get("link-transition-duration");
  transition-property: get("link-transition-properties");
  &:hover,
  &:focus {
    z-index: 2;
    color: color.get(get("link-color-hover"));
    background-color: color.get(get("link-background-color-hover"));
  }
}
#{ $prefix }__selectable {
  padding: 0;
}

// Combine all active selectors using sass:selector functions
$base-selectors: #{ $prefix }__link, #{ $prefix }__toggle;
$active-from-config: get("link-active-selectors");
$traditional-active: sassSelector.append($base-selectors, $active-from-config);

$checked-active: sassSelector.parse("#{ $prefix }__selectable:has(> [type='checkbox']:checked), #{ $prefix }__selectable:has(> [type='radio']:checked)");

#{ $traditional-active, $checked-active },
#{ $prefix }__link[aria-current="page"] {
  &,
  &:hover {
    color: color.get(get("link-color-active"));
    background-color: color.get(get("link-background-color-active"));
  }
}
#{ $prefix }__selectable [type="checkbox"],
#{ $prefix }__selectable [type="radio"],
#{ $prefix }__selectable-input {
  position: absolute;
  top: utils.fallback(get("selectable-input-top"), $selectable-y);
  left: cssvar.use-ulu("menu-stack-link-padding-x");
  font-size: get("selectable-input-font-size");
}
#{ $prefix }__selectable label,
#{ $prefix }__selectable-label {
  width: 100%;
  padding: $selectable-y cssvar.use-ulu("menu-stack-link-padding-x") $selectable-y get("selectable-input-width");
}
#{ $prefix }__link-text {
  display: block;
  flex-grow: 1;
}
#{ $prefix }__link-icon {
  margin-right: get("link-icon-margin");
  flex: 0 0 get("link-icon-width");
  font-size: get("link-icon-font-size");
}
#{ $prefix }__collapsible {
  margin: 0;
  @if (get("toggle-icon-rotate")) {
    &[open] {
      #{ $prefix }__toggle-icon {
        transform: rotate(get("toggle-icon-rotate"));
      }
    }
  }
}
#{ $prefix }__toggle {
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  @include element.summary-remove-marker();  
}

// Modifiers

// Link buttons hang outside in margin so that text optically aligns
#{ $prefix }--hanging {
  &:not(#{ $prefix }--columns, #{ $prefix }--columns-fluid) > #{ $prefix }__list > #{ $prefix }__item,
  &[class*="#{ $prefix-name-only }--columns"] > #{ $prefix }__list > #{ $prefix }__item > #{ $prefix }__list > #{ $prefix }__item {
    > #{ $prefix }__link, 
    > #{ $prefix }__collapsible {
      margin-left: calc(cssvar.use-ulu("menu-stack-link-padding-x") * -1);
      margin-right: calc(cssvar.use-ulu("menu-stack-link-padding-x") * -1);
      width: calc(100% + (cssvar.use-ulu("menu-stack-link-padding-x") * 2));
    }
  }
}

#{ $prefix }--compact {
  $compact-y: get("compact-link-padding-y");
  $compact-x: get("compact-link-padding-x");

  @include cssvar.declare-ulu("menu-stack-link-padding-x", $compact-x);

  #{ $prefix }__selectable,
  #{ $prefix }__toggle,
  #{ $prefix }__link {
    border-radius: get("compact-link-border-radius");
    margin: get("compact-link-margin") 0;
  }
  #{ $prefix }__toggle,
  #{ $prefix }__link {
    padding-top: $compact-y;
    padding-bottom: $compact-y;
  }
  #{ $prefix }__selectable label,
  #{ $prefix }__selectable-label {
    padding-top: $compact-y;
    padding-bottom: $compact-y;
    padding-right: get("compact-selectable-input-width");
  }
  #{ $prefix }__selectable [type="checkbox"],
  #{ $prefix }__selectable [type="radio"],
  #{ $prefix }__selectable-input {
    top: utils.fallback(get("compact-selectable-input-top"), $compact-y);
    font-size: get("compact-selectable-input-font-size");
  }
}

#{ $prefix }--hide-inputs {
  #{ $prefix }__selectable-input,
  #{ $prefix }__selectable [type="checkbox"],
  #{ $prefix }__selectable [type="radio"] {
    @include element.hidden-visually();
  }

  #{ $prefix }__selectable label,
  #{ $prefix }__selectable-label {
    padding-left: get("link-padding-x");
  }
}

#{ $prefix }--stacked {
  @include cssvar.declare-ulu("menu-stack-link-padding-x", get("stacked-link-padding-x"));

  #{ $prefix }__link,
  #{ $prefix }__toggle {
    flex-direction: column;
    justify-content: center;
    text-align: center;
    border-radius: get("stacked-link-border-radius");
    padding-top: get("stacked-link-padding-y");
    padding-bottom: get("stacked-link-padding-y");
    margin: get("stacked-link-margin") 0;
    font-weight: get("stacked-link-font-weight");
  }
  #{ $prefix }__link-icon {
    margin-right: 0;
    margin-bottom: get("stacked-link-icon-margin");

    &:last-child {
      margin-bottom: 0;
    }
  }
}

#{ $prefix }--columns {
  > #{ $prefix }__list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(get("columns-min-width"), 1fr));
    gap: get("columns-gap");
  }
}
#{ $prefix }--columns-fluid {
  > #{ $prefix }__list {
    display: flex;
    flex-wrap: wrap;
    max-width: 100%;
    gap: get("columns-gap");
    > #{ $prefix }__item {
      flex: 0 0 0;
      min-width: get("columns-min-width");
    }
  }
}
// No indenting if we're using columns
[class*="#{ $prefix-name-only }--columns"] {
  > #{ $prefix }__list > #{ $prefix }__item > #{ $prefix }__list {
    padding-left: 0;
  }
}

$prefix: selector.class("modal");
$breakpoint: get("breakpoint");

// // Before it's moved
[data-ulu-modal-builder] {
  display: none;
}

#{ $prefix } {
  // Required for click outside
  position: fixed;
  flex-direction: column;
  // Important: If you use the margin layout system (ie. auto) on dialogs they 
  // can't animate out correctly (thinking it jumps from dialog display system 
  // to normal block and doesn't work. This ALSO affects the z-index (seems to move from top-layer to normal layer). Z-index is for close
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: layout.get("z-index-fixed") + 1;
  margin: 0;
  padding: 0;
  border: 0;
  width: get("width");
  min-width: get("min-width"); // For resizing minimum width
  min-height: get("height");
  max-height: 100vh;
  max-height: 100dvh;
  max-width: 100%;
  overflow-y: hidden;
  box-sizing: border-box;
  box-shadow: get("box-shadow");
  border-radius: get("border-radius");
  background-color: color.get(get("background-color"));
  box-sizing: border-box;
  animation: uluModalCenterOut get("animation-duration-exit") get("animation-timing-function");
  &[open] {
    display: flex;
    animation: uluModalCenterIn get("animation-duration") get("animation-timing-function");
  }
  &::backdrop {
    background: color.get(get("backdrop-color"));
    backdrop-filter: blur(get("backdrop-blur"));
    animation: uluModalBackdropIn get("animation-duration") get("animation-timing-function");
  }
}
#{ $prefix }__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex: 0 0 auto;
  padding: get("header-padding");
  border-bottom: get("header-border-bottom");
  background-color: color.get(get("header-background-color"));
  color: color.get(get("header-color"));
}
#{ $prefix }__body {
  flex: 1 1 auto;
  min-height: 0; // to ensure the flex grow container can get smaller than it's content (and scroll) when needed
  overflow: auto;
  padding: get("body-padding");
}
#{ $prefix }__footer {
  flex: 0 0 auto;
  padding: get("footer-padding");
  background-color: color.get(get("footer-background-color"));
  border-top: get("footer-border-top");
  text-align: get("footer-text-align");
}
#{ $prefix }__title {
  display: flex;
  align-items: baseline;
  margin: 0;
  color: color.get(get("title-color"));
  font-weight: get("title-font-weight");
  font-family: get("title-font-family");
  text-transform: get("title-text-transform");
  line-height: get("title-line-height");
  @if (get("title-size")) {
    @include typography.size(get("title-size"), $only-font-size: true);
  }
}
#{ $prefix }__title-icon {
  margin-right: get("title-icon-margin");
}
#{ $prefix }__close {
  margin: 0 0 0 get("close-margin");
  flex: 0 0 auto;
  background-color: color.get(get("close-background-color"));
  border-color: color.get(utils.fallback(get("close-border-color"), get("close-background-color")));
  color: color.get(get("close-color"));
  box-shadow: get("close-box-shadow");
  &:hover,
  &:focus {
    background-color: color.get(get("close-background-color-hover"));
    color: color.get(get("close-color-hover"));
    border-color: color.get(utils.fallback(get("close-border-color-hover"), get("close-background-color-hover")));
    // need border-color-hover use utils fallback
  }
}

#{ $prefix }__resizer {
  position: absolute;
  overflow: hidden;
  top: 0;
  bottom: 0;
  left: 0;
  width: get("resizer-width");
  display: block;
  cursor: col-resize;
  background-color: color.get(get("resizer-background-color"));
  display: flex;
  align-items: center;
  justify-content: center;
  transition-property: background-color, color;
  transition-duration: 300ms;
  transition-delay: 100ms; 
  color: color.get(get("resizer-color"));
  &:hover {
    color: color.get(get("resizer-color-hover"));
    background-color: color.get(get("resizer-background-color-hover"));
  }
  #{ $prefix }--left & {
    left: auto;
    right: 0;
  }
  #{ $prefix }--center & {
    left: auto;
    right: 0;
    bottom: 0;
    top: auto;
    height: get("resizer-center-size");
    width: get("resizer-center-size");
    background-color: transparent;
    cursor: nwse-resize;
  }
}

// Modifiers
@each $name, $size-width in get("sizes") {
  #{ $prefix }--#{ $name } {
    width: $size-width;
  }
}

// Fullscreen and left and right defaults (width overridden below)
#{ $prefix }--fullscreen,
#{ $prefix }--right,
#{ $prefix }--left {
  @include -fullscreen-common-properties();
}
// Left/Right specific
// - Note these properties are all important even though they seem redundant
//   they are tested and solve quirks with dialog positioning/animation
#{ $prefix }--right,
#{ $prefix }--left {
  width: get("width-left-right");
  top: 0;
  bottom: 0;
  transform: none;
}
#{ $prefix }--top {
  top: 0;
  border-top-right-radius: 0;
  border-top-left-radius: 0;
  transform: translateX(-50%);
  animation: uluModalTopOut get("animation-duration-exit") get("animation-timing-function");
  &[open] {
    animation: uluModalTopIn get("animation-duration") get("animation-timing-function");
  }
}
#{ $prefix }--bottom {
  top: auto;
  bottom: 0;
  transform: translateX(-50%);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  animation: uluModalBottomOut get("animation-duration-exit") get("animation-timing-function");
  &[open] {
    animation: uluModalBottomIn get("animation-duration") get("animation-timing-function");
  }
}
#{ $prefix }--right {
  right: 0;
  left: auto;
  animation: uluModalRightOut get("animation-duration-exit") get("animation-timing-function");
  &[open] {
    animation: uluModalRightIn get("animation-duration") get("animation-timing-function");
  }
}
#{ $prefix }--left {
  left: 0;
  animation: uluModalLeftOut get("animation-duration-exit") get("animation-timing-function");
  &[open] {
    animation: uluModalLeftIn get("animation-duration") get("animation-timing-function");
  }
}
#{ $prefix }--no-header {
  min-height: get("height-no-header");
}
#{ $prefix }--no-backdrop {
  &::backdrop {
    display: none;
  }
}
#{ $prefix }--resize {
  &#{ $prefix }--right  {
    padding-left: get("resizer-width");  
  }
  &#{ $prefix }--left  {
    padding-right: get("resizer-width");  
  }
}
// Share body flush layout
#{ $prefix }--body-fills,
#{ $prefix }--frame-ratio,
#{ $prefix }--frame-fill {
  #{ $prefix }__header {
    border-bottom: none;
  }
  #{ $prefix }__body {
    padding: 0;
  }
}
#{ $prefix }--no-min-height {
  min-height: 0;
}

// Frame layouts for absolute positioned single content (e.g. iframes)
// Both modes use absolute positioning to escape wrappers (p, div, etc)
#{ $prefix }--frame-ratio,
#{ $prefix }--frame-fill {
  #{ $prefix }__body {
    position: relative;
  }
  #{ $prefix }__frame-content {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border: none;
  }
}

// Ratio-specific: disable minimum heights and flex-grow so it perfectly wraps
#{ $prefix }--frame-ratio {
  min-height: 0;
  #{ $prefix }__body {
    flex: none; 
    // Default, can be overridden inline
    aspect-ratio: utils.normalize-aspect-ratio(get("frame-aspect-ratio")); 
  }
}

// Fill-specific: default height
#{ $prefix }--frame-fill {
  #{ $prefix }__body {
    // Default, can be overridden inline
    min-height: get("frame-fill-min-height"); 
  }
}

@if breakpoint.exists($breakpoint) {
  #{ $prefix }--fullscreen-mobile {
    @include breakpoint.max($breakpoint) {
      @include -fullscreen-common-properties();
      top: 50%;
      left: 50%;
      bottom: auto;
      right: auto;
      transform: translate(-50%, -50%);
      animation: uluModalCenterOut get("animation-duration-exit") get("animation-timing-function");
      &[open] {
        animation: uluModalCenterIn get("animation-duration") get("animation-timing-function");
      }
      #{ $prefix }__resizer {
        display: none;
      }
    }
  }
}

// Will display as content when printing
// NOTE: This will not work with native dialog
// Printing works with modal printer by cloning mechanism
