@keyframes uluModalBackdropIn {
  0% {
    background-color: rgba(0, 0, 0, 0);
    backdrop-filter: blur(0);
  }
  100% {
    background-color: color.get(get("backdrop-color"));
    backdrop-filter: blur(get("backdrop-blur"));
  }
}
@keyframes uluModalCenterIn {
  from { 
    opacity: 0; 
    transform: translate(-50%, -40%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translate(-50%, -50%);
    display: flex;
  }
}
@keyframes uluModalCenterOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translate(-50%, -50%);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translate(-50%, 40%);
  }
}
@keyframes uluModalTopIn {
  from { 
    opacity: 0; 
    transform: translate(-50%, -15%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translate(-50%, 0);
    display: flex;
  }
}
@keyframes uluModalTopOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translate(-50%, 0);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translate(-50%, -15%);
  }
}
@keyframes uluModalBottomIn {
  from { 
    opacity: 0; 
    transform: translate(-50%, 15%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translate(-50%, 0);
    display: flex;
  }
}
@keyframes uluModalBottomOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translate(-50%, 0);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translate(-50%, 15%);
  }
}
@keyframes uluModalLeftIn {
  from { 
    opacity: 0; 
    transform: translateX(-15%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translateX(0);
    display: flex;
  }
}
@keyframes uluModalLeftOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translateX(0);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translateX(-15%);
  }
}
@keyframes uluModalRightIn {
  from { 
    opacity: 0; 
    transform: translateX(15%);
    display: none;
  }
  to { 
    opacity: 1; 
    transform: translateX(0);
    display: flex;
  }
}
@keyframes uluModalRightOut {
  from { 
    opacity: 1; 
    display: flex;
    transform: translateX(0);
  }
  to { 
    opacity: 0; 
    display: none;
    transform: translateX(15%);
  }
}

$prefix: selector.class("nav-strip");
#{ $prefix } {
  max-width: 100%; // So ul will overflow
}
// Original thought to not limit to direct child
// auto is for when we don't have control over markup
// The list descendants will be selected that way but the list is
// currently selecting any list/list-item
#{ $prefix }__list,
#{ $prefix }--auto ul {
  display: flex;
  overflow-x: auto;
  line-height: typography.get("line-height-dense");
  gap: get("margin-between");
  @include layout.remove-scrollbar();
}
#{ $prefix }__item,
#{ $prefix }--auto li {
  // layout flex since items inside may not be the same height
  display: flex;
  align-items: flex-end;
}

#{ $prefix }__link,
#{ $prefix }--auto li > a,
#{ $prefix }--auto li > button {
  display: block;
  color: color.get(get("color"));
  padding: get("padding-y") get("padding-x");
  border-top: get("underline-size") solid transparent;
  border-bottom: get("underline-size") solid transparent;
  font-weight: get("font-weight");
  @if (get("nowrap")) {
    white-space: nowrap;
  }
  &:hover,
  &:focus {
    border-bottom-color: color.get(get("underline-color-hover"));
    color: color.get(get("color-hover"));
  }
  #{ get("activeSelector") } {
    border-bottom-color: color.get(get("underline-color"));
    color: color.get(get("color-active"));
  }
}

// Modifiers
#{ $prefix }--right {
  #{ $prefix }__list,
  &#{ $prefix }--auto ul {
    justify-content: flex-end;
  }
}
#{ $prefix }--center {
  #{ $prefix }__list,
  &#{ $prefix }--auto ul {
    justify-content: center;
  }
}
#{ $prefix }--rule {
  position: relative;
  &::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    border-bottom: get("rule-size") solid color.get(get("rule-color"));
  }
  #{ $prefix }__link,
  &#{ $prefix }--auto li > a,
  &#{ $prefix }--auto li > button {
    position: relative;
    z-index: 2;
    margin-bottom: get("rule-offset");
    padding-top: get("padding-y-ruled");
    padding-bottom: get("padding-y-ruled");
  }
}

.overlay-section {
  position: relative;
  display: flex;
  min-height: get("min-height");
  align-items: center;
  justify-content: center;
  padding: get("padding");

  @each $breakpoint, $props in get("breakpoints") {
    $direction: map.get($props, "direction");
    @include breakpoint.from($breakpoint, $direction) {
      padding: map.get($props, "padding");
      min-height: map.get($props, "min-height");
    }
  }
}
.overlay-section__background {
  @include layout.absolute-fill();
  img, 
  video {
    object-fit: cover;
    height: 100%;
    width: 100%;
  }
}
.overlay-section__content {
  position: relative;
  z-index: 2;
  background-color: color.get(get("content-background-color"));
  border: get("content-border");
  flex: 0 1 get("content-width");
  padding: get("content-padding");
  @each $breakpoint, $props in get("breakpoints") {
    $direction: map.get($props, "direction");
    @include breakpoint.from($breakpoint, $direction) {
      padding: map.get($props, "content-padding");
    }
  }
}
.overlay-section--top {
  align-items: flex-start;
}
.overlay-section--bottom {
  align-items: flex-end;
}
.overlay-section--left {
  justify-content: flex-start;
}
.overlay-section--right {
  justify-content: flex-end;
}

.pager {
  font-weight: get("font-weight");
  margin-top: get("margin-top");
  margin-bottom: get("margin-bottom");
}
.pager__items {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}
.pager__item {
  margin: get("item-margin");
  a {

    display: block;
    text-align: center;
    width: get("width");
    height: get("width");
    line-height: get("width");
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: get("border-radius");
    border: get("border-width") solid color.get(get("border-color"));
    background-color: color.get(get("background-color"));
    color: color.get(get("color"));
    &:hover {
      color: color.get(get("color-hover"));
      border-color: color.get(get("border-color-hover"));
      background-color: color.get(get("background-color-hover"));
    }
  }
  &.is-active,
  &--current {
    a, 
    a:hover,
    span {
      font-weight: get("font-weight");
      color: color.get(get("active-color"));
      background-color: color.get(get("active-background-color"));
      border-color: color.get(get("active-border-color"));
    }
  }
}
.pager__item--first,
.pager__item--previous,
.pager__item--next,
.pager__item--last {
  a {
    width: get("action-width");
    height: get("action-width");
    line-height: get("action-width");
    background-color: color.get(get("action-background-color"));
    color: color.get(get("action-color"));
    font-size: 1.2rem;
    line-height: 2.8rem;
    font-weight: bold;
    &:hover {
      border-color: color.get(get("action-border-color-hover"));
      background-color: color.get(get("action-background-color-hover"));
      color: color.get(get("action-color-hover"));
    }
  }
}
.pager__item--previous {
  margin-right: get("action-margin")
}
.pager__item--next {
  margin-left: get("action-margin")
}

$prefix: selector.class("panel");

#{ $prefix } {
  display: flex;
  flex-direction: column;
  overflow: get("overflow");
  background-color: get("background-color");
  box-shadow: get("box-shadow");
  border: get("border");
  border-radius: get("border-radius");
}
#{ $prefix }__row {
  &:first-child {
    border-top-left-radius: get("border-radius");
    border-top-right-radius: get("border-radius");
  }
  &:last-child {
    border-bottom-left-radius: get("border-radius");
    border-bottom-right-radius: get("border-radius");
  }
}

@each $modifier, $rows in $styles {
  @if ($modifier == "default") {
    @each $row-name, $props in $rows {
      @if ($row-name == "default") {
        #{ $prefix }__row {
          @include create-row-style($props);
        }
      } @else {
        #{ $prefix }__row--#{ $row-name } {
          @include create-row-style($props);
        }
      }
    }
  } @else {
    #{ $prefix }--#{ $modifier } {
      @each $row-name, $props in $rows {
        @if ($row-name == "default") {
          #{ $prefix }__row {
