  width: 60%;
  border-radius: get("text-border-radius");
}
#{ $prefix }--inline {
  display: inline-block;
}
#{ $prefix }--inline + #{ $prefix }--inline {
  margin-left: get("inline-margin");
}
#{ $prefix }--background-alt {
