#{ $prefix }__track {
  // @daniel test this
  #{ $prefix }--vertical-center & {
    align-items: center;
  }
}
// Options inner container to limit the controls to the just the track aria
// in order to exclude the dots/nav from the positioning of the controls
#{ $prefix }__control-context {
  position: relative;
}
#{ $prefix }__slide {
  margin: 0;
}
#{ $prefix }--slide-control-margins {
  #{ $prefix }__slide {
    padding: get("padding-top") $slide-padding-x get("padding-bottom") $slide-padding-x;
  }
}
#{ $prefix }__slide-gap-for-controls {
  $padding:  get("button-width") + get("button-margin");
  padding-left: $padding;
  padding-right: $padding;
}
#{ $prefix-plugin }__control-button--previous {
  left: 0;
  margin-left: get("button-offset-x");
}
#{ $prefix-plugin }__control-button--next {
  right: 0;
  margin-right: get("button-offset-x");
}
#{ $prefix }--inset-controls {
  #{ $prefix }__slide-gap-for-controls {
    $padding: get("button-width") + get("button-margin") + get("button-offset-x");
    padding-left: $padding;
    padding-right: $padding;
  }
  #{ $prefix-plugin }__control-button--previous {
    left: 0;
    margin-left: get("button-offset-x");
  }
  #{ $prefix-plugin }__control-button--next {
    right: 0;
    margin-right: get("button-offset-x");
  }
}

$prefix: selector.class("spoke-spinner");


$size: get("size");
$sizeHalf: math.div($size, 2);

$spoke-width: get("spoke-width");
$spoke-widthHalf: math.div($spoke-width, 2);

#{ $prefix } {
  position: relative;
  vertical-align: middle; // When used as inline-block
}
#{ $prefix }__spinner {
  display: inline-block;
  position: relative;
  width: $size;
  height: $size;
}
#{ $prefix }__spinner div {
  transform-origin: $sizeHalf $sizeHalf;
  animation: UluFadeOut get("duration") linear infinite;
}
#{ $prefix }__spinner div::after {
  content: " ";
  display: block;
  position: absolute;
  top: 0;
  left: $sizeHalf - $spoke-widthHalf;
  width: $spoke-width;
  height: get("spoke-height");
  border-radius: get("border-radius");
  background: color.get(get("color"));
}
#{ $prefix }__spinner div:nth-child(1) {
  transform: rotate(0deg);
  animation-delay: -1.1s;
}
#{ $prefix }__spinner div:nth-child(2) {
  transform: rotate(30deg);
  animation-delay: -1s;
}
#{ $prefix }__spinner div:nth-child(3) {
  transform: rotate(60deg);
  animation-delay: -0.9s;
}
#{ $prefix }__spinner div:nth-child(4) {
  transform: rotate(90deg);
  animation-delay: -0.8s;
}
#{ $prefix }__spinner div:nth-child(5) {
  transform: rotate(120deg);
  animation-delay: -0.7s;
}
#{ $prefix }__spinner div:nth-child(6) {
  transform: rotate(150deg);
  animation-delay: -0.6s;
}
#{ $prefix }__spinner div:nth-child(7) {
  transform: rotate(180deg);
  animation-delay: -0.5s;
}
#{ $prefix }__spinner div:nth-child(8) {
  transform: rotate(210deg);
  animation-delay: -0.4s;
}
#{ $prefix }__spinner div:nth-child(9) {
  transform: rotate(240deg);
  animation-delay: -0.3s;
}
#{ $prefix }__spinner div:nth-child(10) {
  transform: rotate(270deg);
  animation-delay: -0.2s;
}
#{ $prefix }__spinner div:nth-child(11) {
  transform: rotate(300deg);
  animation-delay: -0.1s;
}
#{ $prefix }__spinner div:nth-child(12) {
  transform: rotate(330deg);
  animation-delay: 0s;
}

// Map of config props needed for a new style, omitting props like color that aren't required
$required: (
  "size" : get("size"),
  "spoke-width" : get("spoke-width"),
  "spoke-height" : get("spoke-height"),
);

@each $name, $style in $styles {
  $merged: map.merge($required, $style);

  $size: map.get($merged, "size");
  $sizeHalf: math.div($size, 2);

  $spoke-width: map.get($merged, "spoke-width");
  $spoke-widthHalf: math.div($spoke-width, 2);

  #{ $prefix }--#{ $name } {
    #{ $prefix }__spinner {
      width: $size;
      height: $size;
    }
    #{ $prefix }__spinner div {
      transform-origin: $sizeHalf $sizeHalf;
      animation-duration: map.get($merged, "duration");
    }
    #{ $prefix }__spinner div::after {
      left: $sizeHalf - $spoke-widthHalf;
      width: $spoke-width;
      height: map.get($merged, "spoke-height");
      border-radius: map.get($merged, "border-radius");
      background: color.get(map.get($merged, "color"));
    }
  }
}

$prefix: selector.class("sticky-list");
$mask-offset-top: get("mask-offset-top");
$mask-offset-bottom: get("mask-offset-bottom");
$type-size: get("type-size");
$sticky-top: get("sticky-top");

#{ $prefix } {
  padding: get("margin") 0;
}
@include breakpoint.min(get("breakpoint")) {
  #{ $prefix } {
    display: flex;
    align-items: flex-start;
    gap: get("gap");
    position: relative;
    @if ($type-size and typography.has-size($type-size)) {
      @include typography.size($type-size, $only-font-size: true);
    } @else if ($type-size) {
      @warn "Unable to find '#{$type-size}' typography size for title";
    }
  }
  #{ $prefix }__title,
  #{ $prefix } > :not(ul) {
    display: block;
    position: sticky;
    top: $sticky-top;
    flex-basis: get("title-width");
    min-width: get("title-min-width");
    padding-top: $mask-offset-top;
    padding-bottom: $mask-offset-bottom;
    text-align: get("title-text-align");
  }
  #{ $prefix }__list,
  #{ $prefix } > ul {
    list-style: none;
    margin: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-self: stretch;
  }
  #{ $prefix }__item,
  #{ $prefix } > ul > li {
    display: block;
    position: sticky;
    top: $sticky-top;
    margin: 0 !important; // If in editor (to complicated for :not())
    padding: $mask-offset-top get("item-padding-x") $mask-offset-bottom get("item-padding-x");
    @include set-background(get("background-color"));
  }
  #{ $prefix }__item:first-child,
  #{ $prefix } > ul > li:first-child {
    margin-top: 0;
  }
  #{ $prefix }__item:last-child,
  #{ $prefix } > ul > li:last-child {
    margin-bottom: 0;
  }
}

// Print out any contextual background styles
@each $props in get("background-contexts") {
  $selector: map.get($props, "selector");
  $item-padding-x: map.get($props, "item-padding-x");
  @include breakpoint.min(get("breakpoint")) {
    #{ $selector } {
      #{ $prefix }__item,
      #{ $prefix } > ul > li {
        @if ($item-padding-x) {
          padding-left: $item-padding-x;
          padding-right: $item-padding-x;
        }
        @include set-background(map.get($props, "background-color"));
      }
    }
  }
}

$color: color.get($color);
$color-transparent: sassColor.change($color, $alpha: 0);
background-color: $color;
background: linear-gradient(180deg, $color-transparent 0%, $color get("mask-offset-top"));

