$prefix: selector.class("table-scroller");

#{ $prefix } {
  width: 100%;
  overflow-x: auto;
  margin: get("margin");
  > table {
    min-width: 100%;
    max-width: none;
  }
}
#{ $prefix }--nowrap {
  > table > thead th {
    white-space: nowrap;
  }
}

@include utils.file-header("component", "tabs");

$prefix: selector.class("tabs");
$tabpanel-spacing: utils.get-spacing(get("tabpanel-padding"));

#{ $prefix } {
  margin: get("margin");
}

#{ $prefix }__tablist {
  position: relative;
  z-index: 2;
  display: flex; 
  gap: get("tab-gap");
  overflow-x: auto;
  border-bottom: get("tablist-divider");
  border-bottom-width: get("tablist-divider-width");
  @include layout.remove-scrollbar();
}

#{ $prefix }__tab {
  display: block;
  position: relative; 
  cursor: pointer;
  text-align: center;
  padding: get("tab-padding");
  color: color.get(get("tab-color"));
  font-weight: get("tab-font-weight");
  @if (not get("horizontal-tab-wrap")) {
    white-space: nowrap;
  }
  // Indicator
  &::after {
    content: "";
    position: absolute;
    background-color: color.get(get("indicator-color"));
    opacity: 0;
    bottom: 0;
    left: 0;
    right: 0;
    height: get("indicator-size");
    transition-property: opacity, background-color, transform;
    transition-duration: get("indicator-transition-duration");
    transition-timing-function: get("indicator-transition-timing");
    transform: scaleX(get("indicator-scale-start"));
    transform-origin: center;
  }
  &:hover {
    color: color.get(get("tab-color-hover"));
  }
  // Add focus so as user clicks item it starts the active state styling
  &:focus,
  &[aria-selected="true"] {
    @if get("tab-hide-native-focus") {
      outline: none;
    }
    &::after {
      opacity: 1;
      transform: scaleX(1);
    }
  }
  // Add new focus-specific colors
  // Using :focus-visible so it only applies to keyboard focus
  &:focus-visible,
  &[aria-selected="true"]:focus-visible {
    color: color.get(get("tab-color-focus"));
    background-color: color.get(get("tab-background-color-focus"));
  }
  &[aria-selected="true"] {
    color: color.get(get("tab-color-selected"));
    background-color: color.get(get("tab-background-color-selected"));
  }
}

#{ $prefix }__tabpanel {
  position: relative;
  z-index: 1;
  padding: get("tabpanel-padding");
  overflow: hidden;
  background-color: color.get(get("tabpanel-background-color"));
}

// For images, etc that should fill tabpanel
#{ $prefix }__tabpanel-content-fill {
  margin-left: -(map.get($tabpanel-spacing, "left"));
  margin-right: -(map.get($tabpanel-spacing, "right"));
  width: calc(100% + #{ map.get($tabpanel-spacing, "left") + map.get($tabpanel-spacing, "right") });
  max-width: none;
  &:first-child {
    margin-top: -(map.get($tabpanel-spacing, "top"));
  }
  &:last-child {
    margin-bottom: -(map.get($tabpanel-spacing, "bottom"));
  }
}

#{ $prefix }--sticky {
  > #{ $prefix }__tablist {
    position: sticky;
    top: get("sticky-top");
    z-index: get("sticky-z-index");
    background-color: color.get(get("sticky-background-color"));
  }
}

@include breakpoint.min(get("vertical-breakpoint")) {
  #{ $prefix }--vertical {
    display: grid;
    grid-template-columns: get("vertical-tablist-width") auto; 
    > #{ $prefix }__tablist {
      flex-direction: column;
      gap: get("vertical-tab-gap");
      border-right: get("tablist-divider");
      border-right-width: get("vertical-divider-width");
      border-bottom: none;
      grid-column: 1;
    }
    > #{ $prefix }__tablist > #{ $prefix }__tab {
      padding: get("vertical-tab-padding");
      white-space: normal;
      text-align: left;
      &::after {
        left: utils.when(get("vertical-indicator-left"), 0, auto);
        right: utils.when(not get("vertical-indicator-left"), 0, auto);
        bottom: 0;
        top: 0;
        width: get("indicator-size");
        height: auto;
      }
    }
    > #{ $prefix }__tabpanel {
      grid-column: 2; // needed for equalHeights in vertical
    }
  }
  #{ $prefix }--sticky#{ $prefix }--vertical {
    > #{ $prefix }__tablist {
      top: get("sticky-vertical-top");
      align-self: start;
    }
  }
}

#{ $prefix }--transparent {
  > #{ $prefix }__tablist {
    background-color: transparent;
    padding-left: 0;
    padding-right: 0;
  }
  > #{ $prefix }__tabpanel {
    background-color: transparent;
    padding-left: 0;
    padding-right: 0;
  }
}

#{ $prefix }--full-width {
  > #{ $prefix }__tablist {
    justify-content: safe center;
    background-color: color.get(get("full-width-tablist-background-color"));
  }
  > #{ $prefix }__tabpanel {
    background-color: color.get(get("full-width-tabpanel-background-color"));
    padding: 0;
  }
}

// Display all tabs during print
#{ $prefix }--print {
  @media print {
    #{ $prefix }__tablist {
      display: none;
    }
    #{ $prefix }__tabpanel {
      display: block;
      + #{ $prefix }__tabpanel {
        margin-top: get("print-margin");
      }
    }
  }
}

$prefix: selector.class("tag");

#{ $prefix } {
  border-radius: get("border-radius"); 
  display: inline-block;
  padding: get("padding");
  font-weight: get("font-weight");
  vertical-align: get("vertical-align");
  font-style: normal;
  text-overflow: ellipsis;
  text-align: center;
  white-space: nowrap;
  border: get("border-width") solid color.get(get("border-color"));
  background-color: color.get(get("background-color"));
  color: color.get(get("color"));
  font-family: get("font-family");
  line-height: get("line-height");
  @if (typography.has-size(get("type-size"))) {
    @include typography.size(get("type-size"), $only-font-size: true);
  }
  &:not(:last-child) {
    margin-right: get("margin-between");
  }
  &:not(:first-child) {
    margin-left: get("margin-between");
  }
  & + & {
    margin-left: get("margin-between-tags");
  }
}



@each $name, $size in $sizes {
  $type-size: map.get($size, "type-size");

  #{ $prefix }--#{ $name } {
    padding: map.get($size, "padding");  
    line-height: map.get($size, "line-height");
    @if (typography.has-size($type-size)) {
      @include typography.size($type-size, $only-font-size: true);
    }
  }
}

// Order Reason: Needs to inherit from sizes but not styles
#{ $prefix }--counter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: get("counter-size");
  height: get("counter-size");
  border-radius: get("counter-border-radius");
  padding: 0 get("counter-padding-sides");
}

@each $name, $style in $styles {
  #{ $prefix }--#{ $name } {
    background-color: color.get(map.get($style, "background-color")); 
    color: color.get(map.get($style, "color")); 
    border: map.get($style, "border"); 
    border-radius: map.get($style, "border-radius"); 
    border-color: color.get(map.get($style, "border-color")); 
    border-width: map.get($style, "border-width"); 
    box-shadow: map.get($style, "box-shadow"); 
  }
}

$prefix: selector.class("tagged");

#{ $prefix } {
  position: relative;
}
#{ $prefix }__tag {
  position: absolute;
  top: var(--ulu-tagged-y, get("position-y"));
  right: var(--ulu-tagged-x, get("position-x"));
  transform: var(--ulu-tagged-transform, get("transform"));
  margin: 0; // So it doesn't interfere if present
}

$prefix: selector.class("tile-button");

#{ $prefix } {
  white-space: normal;
  margin: 0;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: get("padding");
  border-radius: get("border-radius");
  line-height: get("line-height");
  @if get("transition-enabled") {
    transition-duration: get("transition-duration");
    transition-property: get("transition-properties");
  }
}
#{ $prefix }__row {

  & + & {
    margin-top: get("row-margin");
  }
}

$desc-size: get("description-size");

@if ($desc-size and typography.has-size($desc-size)) {
  #{ $prefix }__row--description {
    @include typography.size($desc-size, $only-font-size: true);
  }
}
// Special row style for icons (optionally transparent)
#{ $prefix }__row--icon {
  margin: 0 auto;
  opacity: get("icon-opacity");
  font-size: get("icon-font-size");
  & + #{ $prefix }__row {
    margin-top: get("icon-margin");
  }
}

$prefix: selector.class("tile-grid");

#{ $prefix } {
  display: grid;
  gap: get("gap");
  grid-template-columns: repeat(auto-fit, minmax(get("width"), 1fr));
  grid-auto-rows: 1fr;
}
#{ $prefix }__item {
  aspect-ratio: get("aspect-ratio");
}
// Use with fill-context, creates the space for images/etc
#{ $prefix }--expanded {
  #{ $prefix }__item {
    width: 100%;
    height: 100%;
    overflow: hidden;
  }
}

// Print out reflowable sizes modifiers
@each $modifier, $props in $sizes {
  $width: map.get($props, "width");
  $gap: map.get($props, "gap");
  $aspect-ratio: map.get($props, "aspect-ratio");

  @if ($width or $gap) {
    #{ $prefix }--#{ $modifier } {
      @if utils.map-has($props, "width") {
        grid-template-columns: repeat(auto-fit, minmax($width, 1fr));
      }
      gap: $gap;
    }
  }
  @if $aspect-ratio {
    #{ $prefix }--#{ $modifier } #{ $prefix }__item {
      aspect-ratio: $aspect-ratio;
    }
  }
}

// Print out the static column styles
// - Adaptive column count per breakpoint, equal widths
@each $modifier, $breakpoints in $static-sizes {
  @include breakpoint.from-each($breakpoints) using ($props) {
    #{ $prefix }--#{ $modifier } {
      grid-template-columns: repeat(map.get($props, "columns"), 1fr);
      gap: map.get($props, "gap");
    }
    @if utils.map-contains-any($props, ("aspect-ratio",)) {
      #{ $prefix }__item {
        aspect-ratio: map.get($props, "aspect-ratio");
      }
    }
  }
}

// Modifier to force no gap on grid
#{ $prefix }--no-gap {
  gap: 0 !important;
}

